INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('66818a0c-c4bd-5623-8594-c198660b4a11', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'c32a7123-0b11-417e-a3dd-2024f9fdf5d2', 'a-level', 'P2.1', '9702 coursebook P2.1 · Planning and analysis', 7, 7, 'A student investigates how the period of a pendulum depends on the length of its string. Which is the independent variable?', NULL, 1, 'multiple_choice'::answer_type, 'The length of the string', NULL, false, NULL, false, NULL, 'The independent variable is the one the experimenter changes deliberately. Mark scheme (1 mark). B1: C (The length of the string).', 1, NULL, NULL),
('f2414d21-671e-5a48-8a93-789e31fe8c73', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'c32a7123-0b11-417e-a3dd-2024f9fdf5d2', 'a-level', 'P2.1', '9702 coursebook P2.1 · Planning and analysis', 8, 8, 'A student records how the current in a thermistor changes as the thermistor is heated in a water bath. Which is the dependent variable?', NULL, 1, 'multiple_choice'::answer_type, 'The current', NULL, false, NULL, false, NULL, 'The dependent variable is the one measured as the other is changed. Mark scheme (1 mark). B1: A (The current).', 1, NULL, NULL),
('39b38f0c-5ff6-5f7e-b67b-d9b623ecacb3', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'c32a7123-0b11-417e-a3dd-2024f9fdf5d2', 'a-level', 'P2.1', '9702 coursebook P2.1 · Planning and analysis', 9, 9, 'In an investigation of how the extension of a spring depends on the load hung from it, which should be a control variable?', NULL, 1, 'multiple_choice'::answer_type, 'The spring used (same material, coil diameter and number of turns)', NULL, false, NULL, false, NULL, 'Everything except the load and the extension must stay the same. Mark scheme (1 mark). B1: D (The spring used (same material, coil diameter and number of turns)).', 1, NULL, NULL),
('90ccfc4e-8917-5fab-ad96-cfb01c50b493', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'c32a7123-0b11-417e-a3dd-2024f9fdf5d2', 'a-level', 'P2.1', '9702 coursebook P2.1 · Planning and analysis', 10, 10, 'It is suggested that y = kx². What gradient would a graph of lg y against lg x have if the suggestion is correct?', NULL, 1, 'numeric'::answer_type, '2', NULL, false, NULL, false, NULL, 'lg y = lg k + 2 lg x, so the gradient is n = 2 × 1 = 2. Mark scheme (2 marks). C1: lg y = n lg x + lg k. A1: gradient = 2.', 2, NULL, NULL),
('aab40a13-0305-5eb6-b4d2-54b9229fea4b', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'c32a7123-0b11-417e-a3dd-2024f9fdf5d2', 'a-level', 'P2.1', '9702 coursebook P2.1 · Planning and analysis', 11, 11, 'The straight line on a graph of lg I against lg d cuts the lg I axis at 1.30. If I = kdⁿ, find k.', NULL, 1, 'numeric'::answer_type, '19.95', NULL, false, NULL, false, NULL, 'lg k = 1.30, so k = 10^1.30 = 20.0. Mark scheme (2 marks). C1: intercept = lg k. A1: k = 20.0.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg076c2bb1-t fg076c2bb1-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg076c2bb1-t">Log–log graph</title><desc id="fg076c2bb1-d">A straight line on a graph of lg I against lg d, falling from the lg I axis, which it cuts at 1.30.</desc><line x1="33" y1="34" x2="33" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="149.4" y1="34" x2="149.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="265.7" y1="34" x2="265.7" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="172.7" x2="382" y2="172.7" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="103.3" x2="382" y2="103.3" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="34" x2="382" y2="34" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="242" x2="388" y2="242" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="242" x2="33" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,242 385.7,245 385.7,239" style="fill:currentColor;stroke:none"/><polygon points="33,24 36,30.3 30.1,30.3" style="fill:currentColor;stroke:none"/><line x1="33" y1="242" x2="33" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="33" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="149.4" y1="242" x2="149.4" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="149.4" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.2</text><line x1="265.7" y1="242" x2="265.7" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="265.7" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.4</text><line x1="382" y1="242" x2="382" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="382" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.6</text><line x1="29" y1="242" x2="33" y2="242" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="242" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="29" y1="172.7" x2="33" y2="172.7" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="172.7" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0.5</text><line x1="29" y1="103.3" x2="33" y2="103.3" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="103.3" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">1.0</text><line x1="29" y1="34" x2="33" y2="34" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="34" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">1.5</text><text x="207.5" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">lg (d / m)</text><text x="29" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">lg (I / W m⁻²)</text><polyline points="33,61.7 382,228.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="41" y="51.7" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">1.30</text></svg>', 'A straight line on a graph of lg I against lg d, falling from the lg I axis, which it cuts at 1.30.'),
('f02d1876-e96a-5de4-ad9b-d8da74908c9d', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'c32a7123-0b11-417e-a3dd-2024f9fdf5d2', 'a-level', 'P2.1', '9702 coursebook P2.1 · Planning and analysis', 12, 12, 'A quantity y is expected to be related to x by y = ax + b, where a and b are constants. Which graph gives a straight line?', NULL, 1, 'multiple_choice'::answer_type, 'y against x', NULL, false, NULL, false, NULL, 'y = ax + b is already the equation of a straight line, gradient a and intercept b. Mark scheme (1 mark). B1: B (y against x).', 1, NULL, NULL),
('aa8d9ab5-0480-5da5-ad0b-0af98fcdfcd2', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'c32a7123-0b11-417e-a3dd-2024f9fdf5d2', 'a-level', 'P2.1', '9702 coursebook P2.1 · Planning and analysis', 13, 13, 'Which graph should be plotted to test whether the period T of a pendulum is proportional to √L?', NULL, 1, 'multiple_choice'::answer_type, 'T against √L', NULL, false, NULL, false, NULL, 'If T ∝ √L, a graph of T against √L is a straight line through the origin. Mark scheme (1 mark). B1: C (T against √L).', 1, NULL, NULL),
('a7f2bd8f-ad8f-580a-a100-6157fae20971', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'c32a7123-0b11-417e-a3dd-2024f9fdf5d2', 'a-level', 'P2.1', '9702 coursebook P2.1 · Planning and analysis', 14, 14, 'For a relationship v = k/u, a student plots v against 1/u. The straight line passes through the origin and the point (0.50, 6.0). Find k.', NULL, 1, 'numeric'::answer_type, '12', NULL, false, NULL, false, NULL, 'k is the gradient: k = 6.0 ÷ 0.50 = 12. Mark scheme (2 marks). C1: gradient = k. A1: k = 12.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg5c61eb5a-t fg5c61eb5a-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg5c61eb5a-t">v against 1/u</title><desc id="fg5c61eb5a-d">A straight line through the origin on a graph of v against 1/u, passing through the point (0.50, 6.0).</desc><line x1="24" y1="34" x2="24" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="83.7" y1="34" x2="83.7" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="143.3" y1="34" x2="143.3" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="203" y1="34" x2="203" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="262.7" y1="34" x2="262.7" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="322.3" y1="34" x2="322.3" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="190" x2="382" y2="190" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="138" x2="382" y2="138" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="86" x2="382" y2="86" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="34" x2="382" y2="34" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="242" x2="388" y2="242" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="242" x2="24" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,242 385.7,245 385.7,239" style="fill:currentColor;stroke:none"/><polygon points="24,24 27,30.3 21,30.3" style="fill:currentColor;stroke:none"/><line x1="24" y1="242" x2="24" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="24" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="83.7" y1="242" x2="83.7" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="83.7" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.1</text><line x1="143.3" y1="242" x2="143.3" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="143.3" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.2</text><line x1="203" y1="242" x2="203" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="203" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.3</text><line x1="262.7" y1="242" x2="262.7" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="262.7" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.4</text><line x1="322.3" y1="242" x2="322.3" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="322.3" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.5</text><line x1="382" y1="242" x2="382" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="382" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.6</text><line x1="20" y1="242" x2="24" y2="242" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="242" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="20" y1="190" x2="24" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="190" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">2</text><line x1="20" y1="138" x2="24" y2="138" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="138" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">4</text><line x1="20" y1="86" x2="24" y2="86" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="86" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">6</text><line x1="20" y1="34" x2="24" y2="34" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="34" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">8</text><text x="203" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1/u</text><text x="20" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">v</text><polyline points="24,242 382,54.8" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="318.3" y1="82" x2="326.3" y2="90" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="318.3" y1="90" x2="326.3" y2="82" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="314.3" y="74" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">(0.50, 6.0)</text></svg>', 'A straight line through the origin on a graph of v against 1/u, passing through the point (0.50, 6.0).'),
('9a425d08-8fbf-58d8-a542-439404984a58', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'c32a7123-0b11-417e-a3dd-2024f9fdf5d2', 'a-level', 'P2.1', '9702 coursebook P2.1 · Planning and analysis', 15, 15, 'What is meant by a control variable in an experiment?', NULL, 1, 'multiple_choice'::answer_type, 'A quantity kept constant so that it cannot affect the dependent variable', NULL, false, NULL, false, NULL, 'Only one variable should be changed at a time. Mark scheme (1 mark). B1: A (A quantity kept constant so that it cannot affect the dependent variable).', 1, NULL, NULL),
('57d34843-f843-595c-93e6-28d0df646b50', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'c32a7123-0b11-417e-a3dd-2024f9fdf5d2', 'a-level', 'P2.1', '9702 coursebook P2.1 · Planning and analysis', 16, 16, 'A student wants to test whether the power P in a resistor is proportional to V². Which graph should give a straight line through the origin?', NULL, 1, 'multiple_choice'::answer_type, 'P against V²', NULL, false, NULL, false, NULL, 'If P = kV², plotting P against V² gives a line of gradient k through the origin. Mark scheme (1 mark). B1: D (P against V²).', 1, NULL, NULL),
('bab9c742-ec28-51ee-9e2e-d3162529a8f6', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'c32a7123-0b11-417e-a3dd-2024f9fdf5d2', 'a-level', 'P2.1', '9702 coursebook P2.1 · Planning and analysis', 17, 17, 'Data suggest that y = 4.0xⁿ. When x = 2.0, y = 32. Calculate n.', NULL, 1, 'numeric'::answer_type, '3', NULL, false, NULL, false, NULL, '2.0ⁿ = 32 ÷ 4.0 = 8, so n = lg 8 ÷ lg 2 = 3.0. Mark scheme (1 mark). A1: n = 3.0.', 1, NULL, NULL),
('b9b4c2f5-9730-51dc-9ca2-3fc07490fd16', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'c32a7123-0b11-417e-a3dd-2024f9fdf5d2', 'a-level', 'P2.1', '9702 coursebook P2.1 · Planning and analysis', 18, 18, 'Why is a graph of lg y against lg x drawn when y = kxⁿ with n unknown?', NULL, 1, 'multiple_choice'::answer_type, 'lg y = n lg x + lg k is a straight-line equation, so n is the gradient', NULL, false, NULL, false, NULL, 'Taking logs turns the power law into a straight line. Mark scheme (1 mark). B1: B (lg y = n lg x + lg k is a straight-line equation, so n is the gradient).', 1, NULL, NULL),
('696fe4f9-3da7-561f-a185-686b695bcaea', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'c32a7123-0b11-417e-a3dd-2024f9fdf5d2', 'a-level', 'P2.1', '9702 coursebook P2.1 · Planning and analysis', 19, 19, 'A graph of ln y against x is a straight line with gradient −0.25 m⁻¹. If y = y₀e^(−kx), state k.', NULL, 1, 'numeric'::answer_type, '0.25', 'm⁻¹', false, NULL, false, NULL, 'ln y = ln y₀ − kx, so k = −(gradient) = −(−0.25) = 0.25 m⁻¹. Mark scheme (2 marks). C1: gradient = −k. A1: k = 0.25 m⁻¹.', 2, NULL, NULL),
('e8583ea7-c1d2-561b-9b7f-5bbfced3bbeb', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'c32a7123-0b11-417e-a3dd-2024f9fdf5d2', 'a-level', 'P2.1', '9702 coursebook P2.1 · Planning and analysis', 20, 20, 'A student changes the angle of a ramp and times a trolley rolling down it. Which is the independent variable?', NULL, 1, 'multiple_choice'::answer_type, 'The angle of the ramp', NULL, false, NULL, false, NULL, 'The angle is the quantity the student chooses to change. Mark scheme (1 mark). B1: C (The angle of the ramp).', 1, NULL, NULL),
