('664bc396-32c0-5f2c-bb0f-9bc0adf94e21', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'c32a7123-0b11-417e-a3dd-2024f9fdf5d2', 'a-level', 'P2.1', '9702 coursebook P2.1 · Planning and analysis', 22, 22, 'What should the hypothesis in an experimental plan state?', NULL, 1, 'multiple_choice'::answer_type, 'The expected relationship between the independent and dependent variables', NULL, false, NULL, false, NULL, 'For example: "T is proportional to √L". Mark scheme (1 mark). B1: A (The expected relationship between the independent and dependent variables).', 1, NULL, NULL),
('d21473eb-998c-5f0b-8a40-0bb642376e04', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'c32a7123-0b11-417e-a3dd-2024f9fdf5d2', 'a-level', 'P2.1', '9702 coursebook P2.1 · Planning and analysis', 23, 23, 'A plan uses a 5 kV supply. Which precaution is appropriate?', NULL, 1, 'multiple_choice'::answer_type, 'Use insulated leads and switch the supply off before changing any connection', NULL, false, NULL, false, NULL, 'High voltages are an electrocution hazard. Mark scheme (1 mark). B1: D (Use insulated leads and switch the supply off before changing any connection).', 1, NULL, NULL),
('3efc2e4c-3026-5504-8a35-1ce00e1a1cd0', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'c32a7123-0b11-417e-a3dd-2024f9fdf5d2', 'a-level', 'P2.1', '9702 coursebook P2.1 · Planning and analysis', 24, 24, 'The intensity I at distance d from a small lamp is thought to follow I = kdⁿ. When d = 0.20 m, I = 25.0 W m⁻²; when d = 0.40 m, I = 6.25 W m⁻². Calculate n.', NULL, 2, 'numeric'::answer_type, '-2', NULL, false, NULL, true, NULL, 'n = lg(6.25 ÷ 25.0) ÷ lg(0.40 ÷ 0.20) = −2.00. Mark scheme (3 marks). C1: ratio of intensities. C1: ratio of distances, logs. A1: n = −2.00.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg1159f922-t fg1159f922-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg1159f922-t">Intensity against distance</title><desc id="fg1159f922-d">Intensity against distance from a small lamp: 25.0 W m⁻² at 0.20 m and 6.25 W m⁻² at 0.40 m, on a smooth falling curve.</desc><line x1="29.4" y1="34" x2="29.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="100" y1="34" x2="100" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="170.5" y1="34" x2="170.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="241" y1="34" x2="241" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="311.5" y1="34" x2="311.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="382" y2="242" style="st