('2ed70352-353b-57c1-851b-a81a9e698a61', '40a9f94f-a554-5168-a0ab-374e29abba04', 'The mass hung from the wire', 'D', false, 3),
('ea4ea004-49c9-58fb-9933-676f06ca3d43', 'aab9b47c-f255-5acb-a8ad-5dbaf9beff05', 't against 1/√(sin θ), expecting a straight line through the origin', 'A', true, 0),
('efec8913-6e45-5005-b5be-669f49f22f63', 'aab9b47c-f255-5acb-a8ad-5dbaf9beff05', 't against θ', 'B', false, 1),
('45241d5c-c731-50fa-928f-e72783808862', 'aab9b47c-f255-5acb-a8ad-5dbaf9beff05', 't² against sin θ', 'C', false, 2),
('31344712-4f9c-5bc3-be4b-af6512ffe01a', 'aab9b47c-f255-5acb-a8ad-5dbaf9beff05', 't against sin θ', 'D', false, 3),
('03d909d5-2937-591a-906a-bab89f1a6ed1', '4909b3c6-e080-5bf9-b3d8-c653523b1cca', 'To produce the final graph', 'A', false, 0),
('a86f221c-f824-572c-a785-db2515375d2c', '4909b3c6-e080-5bf9-b3d8-c653523b1cca', 'To replace repeat readings', 'B', false, 1),
('a5f84114-3722-51f2-ac2e-8e082b071b97', '4909b3c6-e080-5bf9-b3d8-c653523b1cca', 'To avoid calculating uncertainties', 'C', false, 2),
('c6122e56-e106-5fa4-8459-1a154a773221', '4909b3c6-e080-5bf9-b3d8-c653523b1cca', 'To choose suitable ranges, apparatus and values before the main readings are taken', 'D', true, 3),
('56c3525b-71dd-536e-b7c5-03a114b96a51', 'a86cc17a-8482-5390-97fd-a5f833d56f29', 'Wear rubber gloves only', 'A', false, 0),
('8417ce74-8ad3-519d-91bf-8be3c363aad1', 'a86cc17a-8482-5390-97fd-a5f833d56f29', 'Handle it with long tongs, keep it at a distance and minimise the time it is out of its lead box', 'B', true, 1),
('c9d11f64-70f9-5e65-807a-81e62e0b5c31', 'a86cc17a-8482-5390-97fd-a5f833d56f29', 'Keep it in water', 'C', false, 2),
('e236ff7c-954a-5db6-b01f-459e9bd9750d', 'a86cc17a-8482-5390-97fd-a5f833d56f29', 'Hold it close so the count rate is high', 'D', false, 3),
('31be7e7c-2f30-5f61-bab1-93c9e6f89e37', '61e4e478-9513-5a2a-b24a-1bad7958f95e', 'Plot y against x and look for a curve', 'A', false, 0),
('a7a227ed-b5c1-573a-888e-025faa667b9a', '61e4e478-9513-5a2a-b24a-1bad7958f95e', 'Calculate the mean of y', 'B', false, 1),
('e06508d5-dc80-59f8-a05f-41a19155aafb', '61e4e478-9513-5a2a-b24a-1bad7958f95e', 'Plot lg y against lg x: a power law gives a straight line whose gradient is n', 'C', true, 2),
('10eba401-a3d5-5229-9df5-5ca020105ac2', '61e4e478-9513-5a2a-b24a-1bad7958f95e', 'Plot x against y', 'D', false, 3),
('9a4c898d-33b1-5074-8b6d-070f6abc6845', '546b19f6-aaa4-511c-8525-7596a9eb14b6', 'So that the wire does not heat up, because its resistance changes with temperature', 'A', true, 0),
('3f7d3b52-4f59-5e56-a5c4-391af4b7e977', '546b19f6-aaa4-511c-8525-7596a9eb14b6', 'So that the ammeter reads more precisely', 'B', false, 1),
('fd6c75f7-7ead-5f4b-8cc2-3752e06d9634', '546b19f6-aaa4-511c-8525-7596a9eb14b6', 'So that the length stays the same', 'C', false, 2),
('5d377157-502d-529e-a8bb-d548f5e34eec', '546b19f6-aaa4-511c-8525-7596a9eb14b6', 'To save energy from the supply', 'D', false, 3),
('af172565-d469-537c-8dac-96dc7fabd4cd', '5a5e9c71-be1e-54eb-9f60-af4f8cc7d49f', 'Drop one sphere from different heights and time its fall from the top of the tube', 'A', false, 0),
('3106997b-dbce-5478-a162-10a23673881c', '5a5e9c71-be1e-54eb-9f60-af4f8cc7d49f', 'Use spheres of different materials and the same radius', 'B', false, 1),
('228875be-c2fb-573b-a98e-153af7b86fbb', '5a5e9c71-be1e-54eb-9f60-af4f8cc7d49f', 'Time each sphere over the whole tube with a stopwatch and plot v against r only', 'C', false, 2),
('bf19d56c-f711-55cc-b86e-262c630f5b44', '5a5e9c71-be1e-54eb-9f60-af4f8cc7d49f', 'Use spheres of several radii (measured with a micrometer), time each between two marks low in the tube after checking equal times for equal distances, keep the oil at constant temperature, and plot lg v against lg r', 'D', true, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('f06be902-3bc9-5b4b-ba5a-03fcb7cfd0a3', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 7, 7, 'Which instrument is most suitable for measuring the diameter of a wire of about 0.3 mm?', NULL, 1, 'multiple_choice'::answer_type, 'A micrometer screw gauge', NULL, false, NULL, false, NULL, 'A micrometer reads to 0.01 mm. Mark scheme (1 mark). B1: C (A micrometer screw gauge).', 1, NULL, NULL),
('c1bb3037-db26-5abc-8d8c-372a5145e56f', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 8, 8, 'How should a student measure the period of a pendulum of about 1 s most accurately with a stopwatch?', NULL, 1, 'multiple_choice'::answer_type, 'Time 20 oscillations and divide by 20', NULL, false, NULL, false, NULL, 'Timing many oscillations reduces the effect of reaction time. Mark scheme (1 mark). B1: A (Time 20 oscillations and divide by 20).', 1, NULL, NULL),
('ae2f27d7-396b-5757-b074-120902d9e95a', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 9, 9, 'A student times 20 oscillations of a pendulum as 31.6 s. Calculate the period.', NULL, 1, 'numeric'::answer_type, '1.58', 's', false, NULL, false, NULL, 'T = 31.6 ÷ 20 = 1.58 s. Mark scheme (2 marks). C1: total time ÷ number of oscillations. A1: T = 1.58 s.', 2, NULL, NULL),
('f9af2064-46a2-53ed-b460-23619d5ef2e5', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 10, 10, 'A wire about one metre long is stretched along a bench. Which measuring device should a student use to find its full length?', NULL, 1, 'multiple_choice'::answer_type, 'A metre rule', NULL, false, NULL, false, NULL, 'A metre rule reads to 1 mm, enough for about 1 m. Mark scheme (1 mark). B1: D (A metre rule).', 1, NULL, NULL),
('f8aab991-6899-5183-ab07-67f44e0c0825', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 11, 11, 'Which instrument measures the temperature of a water bath during an experiment?', NULL, 1, 'multiple_choice'::answer_type, 'A thermometer (or thermocouple) placed in the water', NULL, false, NULL, false, NULL, 'Temperature is measured directly in the liquid. Mark scheme (1 mark). B1: B (A thermometer (or thermocouple) placed in the water).', 1, NULL, NULL),
('a9a638a6-b493-5482-ba9d-ba4d9633581f', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 12, 12, 'A student plans to vary the load on a wire from 0.5 N to 4.0 N in equal steps, taking 8 readings in all. Calculate the size of each step.', NULL, 1, 'numeric'::answer_type, '0.5', 'N', false, NULL, false, NULL, 'Step = (4.0 − 0.5) ÷ 7 = 0.50 N. Mark scheme (2 marks). C1: 7 intervals for 8 readings. A1: step = 0.50 N.', 2, NULL, NULL),
('c0292897-979f-5be3-9de2-a7beee76c27d', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 13, 13, 'How can a student avoid parallax error when reading the length of a spring against a metre rule?', NULL, 1, 'multiple_choice'::answer_type, 'Read the scale with the eye level with, and perpendicular to, the reading', NULL, false, NULL, false, NULL, 'Viewing at an angle shifts the apparent reading. Mark scheme (1 mark). B1: C (Read the scale with the eye level with, and perpendicular to, the reading).', 1, NULL, NULL),
('d61f475e-8380-5b89-bd9f-9b7866e46913', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 14, 14, 'Which meter, and how connected, is used to measure a current of about 50 mA through a resistor?', NULL, 1, 'multiple_choice'::answer_type, 'A milliammeter in series with the resistor', NULL, false, NULL, false, NULL, 'Ammeters are always connected in series. Mark scheme (1 mark). B1: A (A milliammeter in series with the resistor).', 1, NULL, NULL),
('1838da6c-2981-522e-8e3c-c53bb70b6719', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 15, 15, 'How should a voltmeter be connected to measure the potential difference across a resistor?', NULL, 1, 'multiple_choice'::answer_type, 'In parallel with the resistor', NULL, false, NULL, false, NULL, 'A voltmeter compares the potentials at the two ends. Mark scheme (1 mark). B1: D (In parallel with the resistor).', 1, NULL, NULL),
('7796b3a7-7ec1-537e-bf2e-0de45ea0f796', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 16, 16, 'A micrometer gives a reading of 0.42 mm for a wire, but it reads +0.02 mm when closed. Calculate the true diameter in mm.', NULL, 1, 'numeric'::answer_type, '0.4 mm', 'mm', false, NULL, false, NULL, 'True diameter = 0.42 − 0.02 = 0.40 mm. Mark scheme (2 marks). C1: subtract the zero error. A1: d = 0.40 mm.', 2, NULL, NULL),
('94b85c4d-978e-53e7-ad48-0626a327fc6d', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 17, 17, 'Why should the diameter of a wire be measured at several points along it and in different directions?', NULL, 1, 'multiple_choice'::answer_type, 'The wire may not be uniform or perfectly round, so a mean value is better', NULL, false, NULL, false, NULL, 'Averaging allows for variation in the wire. Mark scheme (1 mark). B1: B (The wire may not be uniform or perfectly round, so a mean value is better).', 1, NULL, NULL),
('c78460df-0863-57c6-893d-04fa40325af8', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 18, 18, 'Why is a fiducial marker placed at the centre of a pendulum''s swing?', NULL, 1, 'multiple_choice'::answer_type, 'To judge the start and end of each oscillation precisely', NULL, false, NULL, false, NULL, 'The bob moves fastest at the centre, so its passage is sharp. Mark scheme (1 mark). B1: C (To judge the start and end of each oscillation precisely).', 1, NULL, NULL),
('1dfce6bc-0c45-5590-b673-fe17e0434a79', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 19, 19, 'A card of length 5.0 cm cuts a light beam for 0.025 s. Calculate the speed of the card.', NULL, 1, 'numeric'::answer_type, '2', 'm s⁻¹', false, NULL, false, NULL, 'v = 0.050 ÷ 0.025 = 2.0 m s⁻¹. Mark scheme (1 mark). A1: v = 2.0 m s⁻¹.', 1, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 190" role="img" aria-labelledby="fgad3f3e8d-t fgad3f3e8d-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgad3f3e8d-t">Card and light gate</title><desc id="fgad3f3e8d-d">A trolley carrying a 5.0 cm card passes through a single light gate.</desc><line x1="20" y1="140" x2="400" y2="140" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="30" y1="140" x2="22" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="70" y1="140" x2="62" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="110" y1="140" x2="102" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="140" x2="142" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="190" y1="140" x2="182" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="230" y1="140" x2="222" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="270" y1="140" x2="262" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="310" y1="140" x2="302" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="350" y1="140" x2="342" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="390" y1="140" x2="382" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="40" y="112" width="70" height="22" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="54" cy="136" r="4" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="96" cy="136" r="4" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="68" y="82" width="14" height="30" rx="0" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="75" y="70" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">5.0 cm card</text><line x1="118" y1="123" x2="144.4" y2="123" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="150,123 142.7,126.4 142.7,119.6" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><path d="M236,136 L236,66 L268,66 L268,136" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="238" y1="95" x2="266" y2="95" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:3 2"/><text x="252" y="54" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">light gate</text></svg>', 'A trolley carrying a 5.0 cm card passes through a single light gate.'),
('300624ac-702b-52e1-a7de-a0ea78dc3f9a', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 20, 20, 'How can a student check that a metre rule clamped next to a hanging spring is vertical?', NULL, 1, 'multiple_choice'::answer_type, 'Use a set square on the bench (or a plumb line) against the rule', NULL, false, NULL, false, NULL, 'A set square or plumb line gives a vertical reference. Mark scheme (1 mark). B1: A (Use a set square on the bench (or a plumb line) against the rule).', 1, NULL, NULL),
('37965a10-a97e-5ac3-baa4-46a8f0ad5316', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 21, 21, 'What is the main advantage of a data logger over taking readings by hand?', NULL, 1, 'multiple_choice'::answer_type, 'It can take many readings at short, precisely timed intervals', NULL, false, NULL, false, NULL, 'Useful for fast changes such as a capacitor discharge. Mark scheme (1 mark). B1: D (It can take many readings at short, precisely timed intervals).', 1, NULL, NULL),
('3b99416d-4774-541f-b53d-f3c07beaa0f0', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 22, 22, 'A stack of 200 identical sheets of paper is 22 mm thick. Calculate the thickness of one sheet, in mm.', NULL, 1, 'numeric'::answer_type, '0.11 mm', 'mm', false, NULL, false, NULL, 't = 22 ÷ 200 = 0.11 mm. Mark scheme (2 marks). C1: total ÷ number. A1: t = 0.11 mm.', 2, NULL, NULL),
('ae0a7950-97d5-59e2-a696-b614b5a8015c', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 23, 23, 'Which instrument is best for measuring the mass of a small object of about 50 g?', NULL, 1, 'multiple_choice'::answer_type, 'A top-pan balance', NULL, false, NULL, false, NULL, 'A top-pan balance reads to 0.1 g or better. Mark scheme (1 mark). B1: B (A top-pan balance).', 1, NULL, NULL),
('c126ed98-6c8c-5310-8de1-8d04379f3088', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 24, 24, 'A metre rule beside a wire shows its ends at the 12.3 cm and 87.6 cm marks. Calculate the length of the wire in cm.', NULL, 1, 'numeric'::answer_type, '75.3 cm', 'cm', false, NULL, false, NULL, 'L = 87.6 − 12.3 = 75.3 cm. Mark scheme (2 marks). C1: difference of readings. A1: L = 75.3 cm.', 2, NULL, NULL),
('cedb725d-325b-5591-8f2e-0f0518bac5ec', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 25, 25, 'Vernier calipers show a main-scale reading of 2.3 cm and the vernier adds 0.07 cm. State the reading, in cm.', NULL, 1, 'numeric'::answer_type, '2.37 cm', 'cm', false, NULL, false, NULL, 'Reading = 2.3 + 0.07 = 2.37 cm. Mark scheme (2 marks). C1: add vernier to main scale. A1: reading = 2.37 cm.', 2, NULL, NULL),
('14f07dd3-d754-5c7e-95a8-92cd7a4c7bc6', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 26, 26, 'How can the time for a ball to fall 0.50 m from rest be measured accurately?', NULL, 2, 'multiple_choice'::answer_type, 'Release it from an electromagnet that starts an electronic timer, and stop the timer with a light gate or trapdoor', NULL, false, NULL, false, NULL, 'The fall time is about 0.3 s, too short for hand timing. Mark scheme (3 marks). C1: electromagnet release. C1: electronic timer/light gate. A1: C (Release it from an electromagnet that starts an electronic timer, and stop the timer with a light gate or trapdoor).', 3, NULL, NULL),
('51dff5ed-26d7-5ed9-a4ff-3d64d6bc9d9b', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 27, 27, 'A student plans to vary the temperature of a thermistor between 20 °C and 80 °C. Which method is best?', NULL, 2, 'multiple_choice'::answer_type, 'Place it in a water bath heated slowly, stirring and reading the temperature with a thermometer close to it', NULL, false, NULL, false, NULL, 'A stirred water bath gives a uniform, measurable temperature. Mark scheme (3 marks). C1: water bath with heater. C1: stir, thermometer near thermistor. A1: A (Place it in a water bath heated slowly, stirring and reading the temperature with a thermometer close to it).', 3, NULL, NULL),
('9154d0d3-777c-57b0-86aa-5f3f63b90624', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 28, 28, 'A student times 20 swings as 26.4 s, with a reaction-time uncertainty of 0.2 s in the total. Calculate the percentage uncertainty in the period.', NULL, 2, 'numeric'::answer_type, '0.7576', '%', false, NULL, false, NULL, '% uncertainty = 0.2 ÷ 26.4 × 100 = 0.758 %. Mark scheme (3 marks). C1: same % for T and total. C1: value. A1: % uncertainty = 0.758%.', 3, NULL, NULL),
('c6c2864a-a60a-504b-a997-b0bf2b5c155e', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 29, 29, 'How should the cross-sectional area of a resistance wire be found in a plan?', NULL, 2, 'multiple_choice'::answer_type, 'Measure the diameter with a micrometer at several places, find the mean and use A = πd²/4', NULL, false, NULL, false, NULL, 'A micrometer gives the small diameter precisely. Mark scheme (3 marks). C1: micrometer, several readings. C1: A = πd²/4. A1: D (Measure the diameter with a micrometer at several places, find the mean and use A = πd²/4).', 3, NULL, NULL),
('2f5b9980-e2d3-5eff-8d62-372d6daea2e8', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 30, 30, 'In a plan to measure the terminal speed of a sphere in a tall tube of oil, how is the terminal speed measured?', NULL, 2, 'multiple_choice'::answer_type, 'Time the sphere between two marks low in the tube, after checking that it takes equal times over equal distances', NULL, false, NULL, false, NULL, 'Only below a certain depth is the speed constant. Mark scheme (3 marks). C1: two marks low down. C1: check constant speed. A1: B (Time the sphere between two marks low in the tube, after checking that it takes equal times over equal distances).', 3, NULL, NULL),
('e7994ca8-6d07-50c1-bdf0-c4da5fcaadd5', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 31, 31, 'A sphere falling at terminal speed takes 1.60 s to pass between two marks 20.0 cm apart. Calculate its terminal speed in m s⁻¹.', NULL, 2, 'numeric'::answer_type, '0.125', 'm s⁻¹', false, NULL, false, NULL, 'v = 0.200 ÷ 1.60 = 0.125 m s⁻¹. Mark scheme (3 marks). C1: cm to m. C1: v = d/t. A1: v = 0.125 m s⁻¹.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 260 320" role="img" aria-labelledby="fgaf8279e9-t fgaf8279e9-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgaf8279e9-t">Terminal speed in oil</title><desc id="fgaf8279e9-d">A tall tube of oil with two marks 20.0 cm apart low down; a sphere falls between them in 1.60 s.</desc><rect x="90" y="52" width="60" height="248" rx="0" style="stroke:none;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="90" y1="30" x2="90" y2="300" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="30" x2="150" y2="300" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="90" y1="300" x2="150" y2="300" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="90" y1="52" x2="150" y2="52" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="80" y1="150" x2="160" y2="150" style="stroke:var(--fig-accent-2,#b45309);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="80" y1="250" x2="160" y2="250" style="stroke:var(--fig-accent-2,#b45309);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="180,150 183,156.3 177,156.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="180" y1="154.9" x2="180" y2="245.1" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="180,250 177,243.7 183,243.7" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="186" y="200" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">20.0 cm</text><circle cx="120" cy="100" r="8" style="stroke:currentColor;stroke-width:2.0;fill:currentColor;stroke-linecap:round;stroke-linejoin:round"/><line x1="120" y1="112" x2="120" y2="136.4" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="120,142 116.6,134.7 123.4,134.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="78" y="100" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">sphere</text><text x="78" y="200" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">marks</text></svg>', 'A tall tube of oil with two marks 20.0 cm apart low down; a sphere falls between them in 1.60 s.'),
('bad0aac3-6cbb-5afa-954f-94f1cd3b71e1', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 32, 32, 'In an investigation of how the current in a wire depends on its length, how is the p.d. across the wire kept constant?', NULL, 2, 'multiple_choice'::answer_type, 'Adjust a variable resistor in series until the voltmeter across the wire shows the same reading each time', NULL, false, NULL, false, NULL, 'The p.d. must be monitored and adjusted. Mark scheme (3 marks). C1: variable resistor. C1: voltmeter monitors p.d. A1: C (Adjust a variable resistor in series until the voltmeter across the wire shows the same reading each time).', 3, NULL, NULL),
('5bd88589-43f9-52c2-b38f-91347dce6cf0', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 33, 33, 'A 12 V supply of negligible internal resistance is to drive a current of no more than 0.50 A through a 4.7 Ω resistor. Calculate the minimum extra series resistance needed.', NULL, 2, 'numeric'::answer_type, '19.3', 'Ω', false, NULL, false, NULL, 'R_total = 12 ÷ 0.50 = 24 Ω, so extra R = 24 − 4.7 = 19.3 Ω. Mark scheme (3 marks). C1: total resistance. C1: subtract 4.7 Ω. A1: R = 19.3 Ω.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 182" role="img" aria-labelledby="fge38b827f-t fge38b827f-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fge38b827f-t">Limiting the current</title><desc id="fge38b827f-d">A 12 V supply, an ammeter, a 4.7 Ω resistor and an extra series resistance R to be chosen so that the current is at most 0.50 A.</desc><line x1="26" y1="48" x2="55.3" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="79.3" y1="48" x2="108.7" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="67.3" cy="48" r="12" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="67.3" y="48.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">A</text><line x1="108.7" y1="48" x2="132" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="168" y1="48" x2="191.3" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="132" y="41" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4.7 Ω</text><line x1="191.3" y1="48" x2="214.7" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="250.7" y1="48" x2="274" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="214.7" y="41" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="216.7" y1="60" x2="244.9" y2="37.1" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="248.7,34 245.6,40.3 241.9,35.7" style="fill:currentColor;stroke:none"/><text x="232.7" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">R = ?</text><line x1="26" y1="142" x2="145" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="142" x2="274" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="145" y1="129" x2="145" y2="155" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="135" x2="155" y2="149" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="166" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">12 V</text><line x1="26" y1="48" x2="26" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="274" y1="48" x2="274" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'A 12 V supply, an ammeter, a 4.7 Ω resistor and an extra series resistance R to be chosen so that the current is at most 0.50 A.'),
('8108d56a-3381-5e65-aa47-5d19fff33313', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 34, 34, 'How should a Hall probe be positioned to measure the largest flux density at a point?', NULL, 2, 'multiple_choice'::answer_type, 'Rotate it until the reading is a maximum, so that its face is perpendicular to the field', NULL, false, NULL, false, NULL, 'The Hall voltage depends on the component of B normal to the probe. Mark scheme (3 marks). C1: rotate to maximum. C1: face perpendicular to B. A1: A (Rotate it until the reading is a maximum, so that its face is perpendicular to the field).', 3, NULL, NULL),
('a05fd347-9478-5157-914a-2ec17db0018a', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 35, 35, 'During a Young modulus experiment, why should the loads be removed one at a time and the extension re-measured?', NULL, 2, 'multiple_choice'::answer_type, 'To check that the wire returns to its original length, so the elastic limit has not been exceeded', NULL, false, NULL, false, NULL, 'Readings beyond the elastic limit would not obey Hooke''s law. Mark scheme (3 marks). C1: unloading readings. C1: elastic limit check. A1: D (To check that the wire returns to its original length, so the elastic limit has not been exceeded).', 3, NULL, NULL),
('0dac2b21-8571-5e4d-b6c1-321edf75229f', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 36, 36, 'A 2.00 m length of wire has a mass of 7.6 g. Calculate its mass per unit length, in units of 10⁻³ kg m⁻¹.', NULL, 2, 'numeric'::answer_type, '3.8', '10⁻³ kg m⁻¹', false, NULL, false, NULL, 'µ = 7.6 × 10⁻³ ÷ 2.00 = 0.00380 kg m⁻¹. Mark scheme (3 marks). C1: g to kg. C1: m/L. A1: µ = 3.8 × 10⁻³ kg m⁻¹.', 3, NULL, NULL),
('fd62ed7a-6b35-55dc-a71e-e4ccaba259d6', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 37, 37, 'An investigation uses a light-dependent resistor and a lamp. How can stray light be prevented from affecting the readings?', NULL, 2, 'multiple_choice'::answer_type, 'Work in a darkened room, or enclose the lamp and LDR in a black tube', NULL, false, NULL, false, NULL, 'Background light changes the LDR resistance. Mark scheme (3 marks). C1: darken room/enclose. C1: background light is a control variable. A1: B (Work in a darkened room, or enclose the lamp and LDR in a black tube).', 3, NULL, NULL),
('84b01ac8-251a-57ed-8c01-55f40e498ef7', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 38, 38, 'The intensity from a small lamp falls as 1/d². An LDR is 0.50 m from the lamp. How far from the lamp should it be moved so that the intensity halves?', NULL, 2, 'numeric'::answer_type, '0.7071', 'm', false, NULL, false, NULL, 'I ∝ 1/d², so d₂ = 0.50 × √2 = 0.707 m. Mark scheme (4 marks). M1: inverse square. C1: d ∝ 1/√I. C1: value. A1: d = 0.707 m.', 4, NULL, NULL),
('d7b14581-b611-517f-9f7d-45ca4d78a487', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 39, 39, 'Why should readings of the dependent variable be repeated at each value of the independent variable?', NULL, 2, 'multiple_choice'::answer_type, 'Repeats show the spread of the readings, reveal anomalies and give a mean with less random error', NULL, false, NULL, false, NULL, 'The half-range of repeats also estimates the uncertainty. Mark scheme (3 marks). C1: mean reduces random error. C1: identifies anomalies/uncertainty. A1: C (Repeats show the spread of the readings, reveal anomalies and give a mean with less random error).', 3, NULL, NULL),
('75da7f42-cd48-5acc-9072-121d38dc8f49', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 40, 40, 'Why should the independent variable be varied over as wide a range as possible?', NULL, 2, 'multiple_choice'::answer_type, 'A wide range shows the trend clearly and lets the gradient be found more precisely', NULL, false, NULL, false, NULL, 'Closely bunched points give a poorly defined gradient. Mark scheme (3 marks). C1: trend over range. C1: precise gradient. A1: A (A wide range shows the trend clearly and lets the gradient be found more precisely).', 3, NULL, NULL),
('a5309bec-a680-5654-aa5d-f7acc9b1bd78', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 41, 41, 'In a plan, the time for 10 oscillations of a spring–mass system is expected to be about 6 s. With a reaction-time uncertainty of 0.2 s, calculate the percentage uncertainty in the period.', NULL, 2, 'numeric'::answer_type, '3.333', '%', false, NULL, false, NULL, '% uncertainty = 0.2 ÷ 6 × 100 = 3.33 %. Mark scheme (3 marks). C1: absolute ÷ total. C1: × 100. A1: % uncertainty = 3.33%.', 3, NULL, NULL),
('b460fb74-e912-562b-bbbe-8742873dd75c', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 42, 42, 'Which plan best determines how the period T of a mass–spring system depends on the mass m?', NULL, 3, 'multiple_choice'::answer_type, 'Use one spring; add slotted masses measured on a balance; time 20 oscillations for each with a fiducial mark, repeating; plot lg T against lg m', NULL, false, NULL, false, NULL, 'Only m is varied; many oscillations and repeats reduce uncertainty; a log graph finds the power. Mark scheme (5 marks). C1: same spring (control). C1: mass measured on balance. C1: time many oscillations, fiducial mark. C1: log–log analysis. A1: D (Use one spring; add slotted masses measured on a balance; time 20 oscillations for each with a fiducial mark, repeating; plot lg T against lg m).', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 300" role="img" aria-labelledby="fg01a35ce9-t fg01a35ce9-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg01a35ce9-t">Mass–spring system</title><desc id="fg01a35ce9-d">A mass hanging on a vertical spring, set oscillating vertically; slotted masses can be added.</desc><line x1="70" y1="40" x2="190" y2="40" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="76" y1="40" x2="68" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="88" y1="40" x2="80" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="100" y1="40" x2="92" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="112" y1="40" x2="104" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="124" y1="40" x2="116" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136" y1="40" x2="128" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="148" y1="40" x2="140" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="160" y1="40" x2="152" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="172" y1="40" x2="164" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="184" y1="40" x2="176" y2="32" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polyline points="130,40 130,50 121,56.9 139,63.8 121,70.6 139,77.5 121,84.4 139,91.2 121,98.1 139,105 121,111.9 139,118.8 121,125.6 139,132.5 121,139.4 139,146.2 121,153.1 130,160 130,170" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="100" y="170" width="60" height="40" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="130" y="190" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">m</text></svg>', 'A mass hanging on a vertical spring, set oscillating vertically; slotted masses can be added.'),
('ad050893-af36-504a-8b60-85fcf90aab37', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 43, 43, 'A wire of length 0.800 m and diameter 0.32 mm has a resistance of 5.6 Ω. (a) Calculate its cross-sectional area. (b) Calculate the resistivity of its metal, in units of 10⁻⁷ Ω m.', NULL, 3, 'numeric'::answer_type, '5.63', '10⁻⁷ Ω m', false, NULL, false, NULL, '(a) A = π × (0.16 × 10⁻³)² = 8.042 × 10⁻⁸ m². (b) ρ = RA/L = 5.6 × 8.042 × 10⁻⁸ ÷ 0.800 = 5.63 × 10⁻⁷ Ω m. Mark scheme (5 marks). C1: radius from diameter. C1: area. M1: ρ = RA/L. C1: substitution. A1: ρ = 5.63 × 10⁻⁷ Ω m.', 5, NULL, NULL),
('fdc277da-940e-57c7-80ef-bea682c6bbf1', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 44, 44, 'A tuning fork of 500 Hz is held over a tube closed at one end. Resonance occurs at air-column lengths of 0.165 m and 0.505 m. (a) Explain why the difference is half a wavelength. (b) Calculate the wavelength. (c) Calculate the speed of sound.', NULL, 3, 'numeric'::answer_type, '340', 'm s⁻¹', false, NULL, false, NULL, '(a) Successive resonances differ by one loop of the standing wave, λ/2. (b) λ = 2 × (0.505 − 0.165) = 0.68 m. (c) v = fλ = 500 × 0.68 = 340 m s⁻¹. Mark scheme (6 marks). B1: successive resonances λ/2 apart. C1: difference. C1: λ. M1: v = fλ. C1: value. A1: v = 340 m s⁻¹.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 330" role="img" aria-labelledby="fg2367ae86-t fg2367ae86-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg2367ae86-t">Resonance tube</title><desc id="fg2367ae86-d">A tube open at the top dipping into water, with a 500 Hz tuning fork above; resonance occurs when the air column is 0.165 m long and again at 0.505 m.</desc><rect x="110" y="266.4" width="40" height="38.6" rx="0" style="stroke:none;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="110" y1="70" x2="110" y2="305" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="70" x2="150" y2="305" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="104" y1="134.2" x2="156" y2="134.2" style="stroke:var(--fig-accent-2,#b45309);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:5 4"/><line x1="110" y1="266.4" x2="150" y2="266.4" style="stroke:var(--fig-accent-2,#b45309);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M122,26 L122,52 Q130,62 138,52 L138,26" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="130" y1="58" x2="130" y2="68" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="148" y="36" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">500 Hz</text><polygon points="174,70 177,76.3 171,76.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="174" y1="74.9" x2="174" y2="129.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="174,134.2 171,127.8 177,127.8" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="180" y="102.1" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">0.165 m</text><polygon points="86,70 89,76.3 83,76.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="86" y1="74.9" x2="86" y2="261.5" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="86,266.4 83,260.1 89,260.1" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="80" y="168.2" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0.505 m</text><text x="162" y="150.2" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">first</text><text x="162" y="282.4" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">second</text></svg>', 'A tube open at the top dipping into water, with a 500 Hz tuning fork above; resonance occurs when the air column is 0.165 m long and again at 0.505 m.'),
('91de8246-b6a8-51c9-bc0d-73a229586d30', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 45, 45, 'A wire 2.50 m long and 0.50 mm in diameter extends by 2.4 mm under a load of 40 N. (a) Calculate the stress. (b) Calculate the Young modulus, in units of 10¹¹ Pa.', NULL, 3, 'numeric'::answer_type, '2.122', '10¹¹ Pa', false, NULL, false, NULL, '(a) A = π × (0.25 × 10⁻³)² = 1.963 × 10⁻⁷ m²; stress = 40 ÷ 1.963 × 10⁻⁷ = 2.037 × 10⁸ Pa. (b) E = 2.037 × 10⁸ ÷ (2.4 × 10⁻³ ÷ 2.50) = 2.12 × 10¹¹ Pa. Mark scheme (5 marks). C1: area. C1: stress. M1: strain = e/L. C1: E = stress/strain. A1: E = 2.12 × 10¹¹ Pa.', 5, NULL, NULL),
('76132742-5aa5-5abd-ae79-4c1caa56b494', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 46, 46, 'A coil of wire is heated in a water bath from 20 °C to 90 °C to see how its resistance changes. Which set of controls and precautions is most complete?', NULL, 3, 'multiple_choice'::answer_type, 'Stir the water and wait for steady readings; keep the current small to avoid self-heating; use the same coil and meter throughout; take care with hot water and keep electrical connections dry', NULL, false, NULL, false, NULL, 'Uniform temperature, no self-heating, same apparatus, and safety with hot water and electricity. Mark scheme (5 marks). C1: stir/equilibrium. C1: small current. C1: same coil and meters. C1: safety. A1: B (Stir the water and wait for steady readings; keep the current small to avoid self-heating; use the same coil and meter throughout; take care with hot water and keep electrical connections dry).', 5, NULL, NULL),
('4f52d738-0af5-52f8-90ac-a9de1829cb38', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 47, 47, 'A 50 W heater runs for 300 s in a 0.80 kg aluminium block and its temperature rises by 18.5 K. (a) Calculate the energy supplied. (b) Calculate the specific heat capacity of aluminium, ignoring losses.', NULL, 3, 'numeric'::answer_type, '1014', 'J kg⁻¹ K⁻¹', false, NULL, false, NULL, '(a) E = 50 × 300 = 15 000 J. (b) c = 15 000 ÷ (0.80 × 18.5) = 1010 J kg⁻¹ K⁻¹. Mark scheme (5 marks). C1: E = Pt. M1: c = E/(mΔθ). C1: substitution. C1: unit. A1: c = 1010 J kg⁻¹ K⁻¹.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 450 250" role="img" aria-labelledby="fgbd204017-t fgbd204017-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgbd204017-t">Electrical heating of a block</title><desc id="fgbd204017-d">A 50 W heater and a thermometer in an insulated 0.80 kg aluminium block, with an ammeter in series with the heater and a voltmeter across it.</desc><g transform="translate(0,0)"><rect x="20" y="60" width="180" height="160" rx="0" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 3"/><rect x="30" y="70" width="160" height="140" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="110" y="236" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">insulation</text><rect x="72" y="40" width="16" height="110" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-muted,#6b7280);stroke-linecap:round;stroke-linejoin:round"/><text x="80" y="28" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">heater</text><rect x="141" y="20" width="8" height=