th:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="76" y="90.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">V</text><circle cx="42" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><circle cx="110" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><line x1="126" y1="48" x2="148" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="172" y1="48" x2="194" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="160" cy="48" r="12" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="160" y="48.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">A</text><line x1="26" y1="184" x2="105" y2="184" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="115" y1="184" x2="194" y2="184" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="105" y1="171" x2="105" y2="197" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="115" y1="177" x2="115" y2="191" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="110" y="208" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">50 W</text><line x1="26" y1="48" x2="26" y2="184" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="194" y1="48" x2="194" y2="184" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></g></svg>', 'A 50 W heater and a thermometer in an insulated 0.80 kg aluminium block, with an ammeter in series with the heater and a voltmeter across it.'),
('230e6e42-b89a-5043-b5bb-eacdb0100770', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 48, 48, 'An LDR whose resistance varies from 2.0 kΩ (bright) to 20 kΩ (dark) is in series with a 10 kΩ resistor across a 6.0 V supply. The output is taken across the 10 kΩ resistor. (a) Calculate the output in bright light. (b) Calculate the output in the dark. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '2', 'V', false, NULL, false, NULL, '(a) V = 6.0 × 10 ÷ (10 + 2.0) = 5.00 V. (b) V = 6.0 × 10 ÷ (10 + 20) = 2.00 V. Mark scheme (6 marks). M1: potential divider ratio. C1: bright value. C1: total resistance in dark. C1: substitution. C1: value. A1: V = 2.0 V.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 236" role="img" aria-labelledby="fg45d699ee-t fg45d699ee-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg45d699ee-t">LDR potential divider</title><desc id="fg45d699ee-d">A 6.0 V supply across an LDR in series with a 10 kΩ resistor; the output voltmeter is across the 10 kΩ resistor.</desc><line x1="26" y1="48" x2="62" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="98" y1="48" x2="134" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="62" y="41" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="80" cy="48" r="24" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="52" y1="14" x2="61.7" y2="28.5" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="64,32 58.9,28.9 63.1,26.1" style="fill:currentColor;stroke:none"/><line x1="64" y1="14" x2="73.7" y2="28.5" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="76,32 70.9,28.9 75.1,26.1" style="fill:currentColor;stroke:none"/><text x="80" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">LDR</text><line x1="134" y1="48" x2="150" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="48" x2="274" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="48" x2="150" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="48" x2="258" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="48" x2="186" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="222" y1="48" x2="258" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="186" y="41" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="204" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">10 kΩ</text><line x1="150" y1="102" x2="192" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="216" y1="102" x2="258" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="204" cy="102" r="12" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="204" y="102.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">V</text><text x="204" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">output</text><circle cx="150" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><circle cx="258" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><line x1="26" y1="196" x2="145" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="196" x2="274" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="145" y1="183" x2="145" y2="209" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="189" x2="155" y2="203" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="220" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">6.0 V</text><line x1="26" y1="48" x2="26" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="274" y1="48" x2="274" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'A 6.0 V supply across an LDR in series with a 10 kΩ resistor; the output voltmeter is across the 10 kΩ resistor.'),
('228bf74c-152f-53ef-b24d-460a8a380a30', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 49, 49, 'A plan must measure g to better than 1% with a falling ball. Which choice of apparatus and method is best?', NULL, 3, 'multiple_choice'::answer_type, 'Electromagnet release and light gates connected to an electronic timer; several heights measured with a metre rule; plot h against t² and use the gradient', NULL, false, NULL, false, NULL, 'Fall times are short, so electronic timing and a graph over several heights are needed. Mark scheme (5 marks). C1: electronic timing. C1: several heights. C1: graph of h against t². C1: g = 2 × gradient. A1: C (Electromagnet release and light gates connected to an electronic timer; several heights measured with a metre rule; plot h against t² and use the gradient).', 5, NULL, NULL),
('9934ede1-ecf8-54f2-ba03-53860cd444ab', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 50, 50, 'A pendulum has a period of about 0.80 s. The total time is measured with a reaction-time uncertainty of 0.2 s. (a) Find the shortest total time for a percentage uncertainty of 1%. (b) Calculate the minimum number of oscillations to time.', NULL, 3, 'numeric'::answer_type, '25', NULL, false, NULL, false, NULL, '(a) t = 0.2 ÷ 0.01 = 20 s. (b) n = 20 ÷ 0.80 = 25. Mark scheme (5 marks). M1: % uncertainty = 0.2/t. C1: t = 20 s. M1: n = t/T. C1: value. A1: n = 25.', 5, NULL, NULL),
('86e71ef4-c8f2-542a-b1d0-25dbb89e1e71', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '41348043-60df-4740-a4bb-9fdc383dd64d', 'a-level', 'P2.2', '9702 coursebook P2.2 · Planning', 51, 51, 'A card 4.0 cm long passes through two light gates 0.60 m apart, cutting the beams for 0.080 s and then 0.040 s. (a) Calculate both speeds. (b) Calculate the acceleration.', NULL, 3, 'numeric'::answer_type, '0.625', 'm s⁻²', false, NULL, false, NULL, '(a) u = 0.040 ÷ 0.080 = 0.50 m s⁻¹; v = 0.040 ÷ 0.040 = 1.0 m s⁻¹. (b) a = (1.0² − 0.50²) ÷ (2 × 0.60) = 0.625 m s⁻². Mark scheme (5 marks). C1: u. C1: v. M1: v² = u² + 2as. C1: value. A1: a = 0.625 m s⁻².', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 190" role="img" aria-labelledby="fg1bbeff0b-t fg1bbeff0b-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg1bbeff0b-t">Two light gates</title><desc id="fg1bbeff0b-d">A trolley carrying a 4.0 cm card runs along a track through light gates A and B, 0.60 m apart.</desc><line x1="20" y1="140" x2="400" y2="140" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="30" y1="140" x2="22" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="70" y1="140" x2="62" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="110" y1="140" x2="102" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="140" x2="142" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="190" y1="140" x2="182" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="230" y1="140" x2="222" y2="148" style="stroke:currentColor;stroke-width:0.9;fill