('4e5c64e7-16c4-58c6-b585-8d0b38779fe8', 'fd62ed7a-6b35-55dc-a71e-e4ccaba259d6', 'Use a brighter lamp', 'A', false, 0),
('2f378621-d339-5964-ad1a-60f1cb1af964', 'fd62ed7a-6b35-55dc-a71e-e4ccaba259d6', 'Work in a darkened room, or enclose the lamp and LDR in a black tube', 'B', true, 1),
('b3b861c0-0be6-5ff7-a236-ad1bd3ef1376', 'fd62ed7a-6b35-55dc-a71e-e4ccaba259d6', 'Use a larger LDR', 'C', false, 2),
('e7875ab7-7033-55c1-ae33-7d467d775c16', 'fd62ed7a-6b35-55dc-a71e-e4ccaba259d6', 'Take readings quickly', 'D', false, 3),
('078a6e73-2fdc-5066-bc10-08d45a9391ea', 'd7b14581-b611-517f-9f7d-45ca4d78a487', 'Repeats remove systematic errors', 'A', false, 0),
('f10cb19d-dd01-5468-818d-eebe3ffd628b', 'd7b14581-b611-517f-9f7d-45ca4d78a487', 'Repeats make the range wider', 'B', false, 1),
('d996001a-ebea-59a9-b55b-27056ae1356b', 'd7b14581-b611-517f-9f7d-45ca4d78a487', 'Repeats show the spread of the readings, reveal anomalies and give a mean with less random error', 'C', true, 2),
('22fbe3e9-df47-567a-b3d9-f6904821daa9', 'd7b14581-b611-517f-9f7d-45ca4d78a487', 'Repeats are needed only if the first reading is zero', 'D', false, 3),
('fac47846-1167-5313-99f9-0e50d51b45d5', '75da7f42-cd48-5acc-9072-121d38dc8f49', 'A wide range shows the trend clearly and lets the gradient be found more precisely', 'A', true, 0),
('c41766c6-c680-542f-930f-0bd9929e8788', '75da7f42-cd48-5acc-9072-121d38dc8f49', 'It reduces the number of readings needed', 'B', false, 1),
('0ac28eb1-25d0-5968-8367-97bc6698a176', '75da7f42-cd48-5acc-9072-121d38dc8f49', 'It removes systematic errors', 'C', false, 2),
('1eddb225-72ca-5c40-b2c4-6a4968f53afb', '75da7f42-cd48-5acc-9072-121d38dc8f49', 'It keeps the apparatus safe', 'D', false, 3),
('29a67653-8546-54a7-802f-03cd39879420', 'b460fb74-e912-562b-bbbe-8742873dd75c', 'Use a different spring for each mass and time one oscillation', 'A', false, 0),
('db4ce3f0-d001-5cf4-8d2d-0bf33353ad2e', 'b460fb74-e912-562b-bbbe-8742873dd75c', 'Keep the mass fixed and change the amplitude', 'B', false, 1),
('29a560a8-fe2c-5491-9b42-3c1204d14c10', 'b460fb74-e912-562b-bbbe-8742873dd75c', 'Time oscillations with a large amplitude so they are easy to see, and plot T against m only', 'C', false, 2),
('e65ce8b5-a295-515c-bc0a-2faae3e91396', 'b460fb74-e912-562b-bbbe-8742873dd75c', 'Use one spring; add slotted masses measured on a balance; time 20 oscillations for each with a fiducial mark, repeating; plot lg T against lg m', 'D', true, 3),
('8e205357-91dd-5de2-8049-fb0f654f6721', '76132742-5aa5-5abd-ae79-4c1caa56b494', 'Heat quickly with a large current; read once at each temperature', 'A', false, 0),
('1f37d339-84b3-560a-97fe-6be2303f71b6', '76132742-5aa5-5abd-ae79-4c1caa56b494', 'Stir the water and wait for steady readings; keep the current small to avoid self-heating; use the same coil and meter throughout; take care with hot water and keep electrical connections dry', 'B', true, 1),
('56b10e8d-bffb-5cbd-ad1e-2a348b224340', '76132742-5aa5-5abd-ae79-4c1caa56b494', 'Use a new coil at each temperature', 'C', false, 2),
('d083e8c6-da6b-510b-8b00-0cbb82a65c3f', '76132742-5aa5-5abd-ae79-4c1caa56b494', 'Measure only at 20 °C and 90 °C', 'D', false, 3),
('7a998361-d52b-52e8-8bcb-4a37c0be1d6c', '228bf74c-152f-53ef-b24d-460a8a380a30', 'A stopwatch and a single height of 0.5 m', 'A', false, 0),
('f7756062-f32d-5485-844b-2784bd059afb', '228bf74c-152f-53ef-b24d-460a8a380a30', 'A stopwatch and a ruler held by hand', 'B', false, 1),
('8144c343-1e7d-5c39-b88d-b0f5ffe05926', '228bf74c-152f-53ef-b24d-460a8a380a30', 'Electromagnet release and light gates connected to an electronic timer; several heights measured with a metre rule; plot h against t² and use the gradient', 'C', true, 2),
('3208d09b-6c82-5c70-a95e-0f0a2b677070', '228bf74c-152f-53ef-b24d-460a8a380a30', 'A video at 10 frames per second', 'D', false, 3)
