('df8ccf75-cd75-5819-848d-cc30ba8be996', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 7, 7, 'A straight line on a graph passes through (0.0, 1.2) and (4.0, 9.2). Calculate its gradient.', NULL, 1, 'numeric'::answer_type, '2', NULL, false, NULL, false, NULL, 'Gradient = (9.2 − 1.2) ÷ (4.0 − 0.0) = 2.0. Mark scheme (2 marks). C1: Δy/Δx. A1: gradient = 2.0.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fgbb2300aa-t fgbb2300aa-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgbb2300aa-t">A straight-line graph</title><desc id="fgbb2300aa-d">A straight line through (0.0, 1.2) and (4.0, 9.2).</desc><line x1="29.4" y1="34" x2="29.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="100" y1="34" x2="100" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="170.5" y1="34" x2="170.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="241" y1="34" x2="241" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="311.5" y1="34" x2="311.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="207.3" x2="382" y2="207.3" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="172.7" x2="382" y2="172.7" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="138" x2="382" y2="138" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="103.3" x2="382" y2="103.3" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="68.7" x2="382" y2="68.7" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="34" x2="382" y2="34" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="388" y2="242" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="29.4" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,242 385.7,245 385.7,239" style="fill:currentColor;stroke:none"/><polygon points="29.4,24 32.4,30.3 26.5,30.3" style="fill:currentColor;stroke:none"/><line x1="29.4" y1="242" x2="29.4" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.4" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="100" y1="242" x2="100" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="100" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1</text><line x1="170.5" y1="242" x2="170.5" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="170.5" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2</text><line x1="241" y1="242" x2="241" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="241" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">3</text><line x1="311.5" y1="242" x2="311.5" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="311.5" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4</text><line x1="382" y1="242" x2="382" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="382" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">5</text><line x1="25.4" y1="242" x2="29.4" y2="242" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="242" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="25.4" y1="207.3" x2="29.4" y2="207.3" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="207.3" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">2</text><line x1="25.4" y1="172.7" x2="29.4" y2="172.7" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="172.7" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">4</text><line x1="25.4" y1="138" x2="29.4" y2="138" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="138" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">6</text><line x1="25.4" y1="103.3" x2="29.4" y2="103.3" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="103.3" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">8</text><line x1="25.4" y1="68.7" x2="29.4" y2="68.7" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="68.7" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">10</text><line x1="25.4" y1="34" x2="29.4" y2="34" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="34" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">12</text><text x="205.7" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">x</text><text x="25.4" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">y</text><polyline points="29.4,221.2 382,47.9" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="25.4" y1="217.2" x2="33.4" y2="225.2" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="25.4" y1="225.2" x2="33.4" y2="217.2" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="307.5" y1="78.5" x2="315.5" y2="86.5" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="307.5" y1="86.5" x2="315.5" y2="78.5" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="39.4" y="227.2" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">(0.0, 1.2)</text><text x="321.5" y="88.5" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">(4.0, 9.2)</text></svg>', 'A straight line through (0.0, 1.2) and (4.0, 9.2).'),
('b99fab9a-8aee-5d34-99e7-63797e0c5b0c', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 8, 8, 'A line of gradient 2.5 passes through the point (2.0, 7.0). Find where it crosses the y-axis.', NULL, 1, 'numeric'::answer_type, '2', NULL, false, NULL, false, NULL, 'c = y − mx = 7.0 − 2.5 × 2.0 = 2.0. Mark scheme (2 marks). C1: c = y − mx. A1: c = 2.0.', 2, NULL, NULL),
('d713a3d1-00d7-5b51-8778-dcd4d0b77320', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 9, 9, 'For v² = u² + 2as, which graph gives a straight line from which a is found?', NULL, 1, 'multiple_choice'::answer_type, 'v² against s, with gradient 2a', NULL, false, NULL, false, NULL, 'Compare with y = mx + c: y = v², x = s, m = 2a, c = u². Mark scheme (1 mark). B1: C (v² against s, with gradient 2a).', 1, NULL, NULL),
('ef03cf25-7f52-5b0f-babd-59da9ac06aea', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 10, 10, 'A graph of v² against s for a trolley has gradient 4.6 m s⁻². Calculate the acceleration.', NULL, 1, 'numeric'::answer_type, '2.3', 'm s⁻²', false, NULL, false, NULL, 'Gradient = 2a, so a = 4.6 ÷ 2 = 2.3 m s⁻². Mark scheme (2 marks). C1: gradient = 2a. A1: a = 2.3 m s⁻².', 2, NULL, NULL),
('4f7c35bd-c98d-5bc1-94bc-92f6b8df61ff', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 11, 11, 'For a wire, R = ρL/A. If R is plotted against L, what is the gradient?', NULL, 1, 'multiple_choice'::answer_type, 'ρ/A', NULL, false, NULL, false, NULL, 'R = (ρ/A)L is a line through the origin of gradient ρ/A. Mark scheme (1 mark). B1: A (ρ/A).', 1, NULL, NULL),
('72e00ee0-76e5-50f1-a1a9-3fa8e798d160', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 12, 12, 'A graph of R against L for a wire of cross-sectional area 1.5 × 10⁻⁷ m² has gradient 12 Ω m⁻¹. Calculate the resistivity, in units of 10⁻⁶ Ω m.', NULL, 1, 'numeric'::answer_type, '1.8', '10⁻⁶ Ω m', false, NULL, false, NULL, 'ρ = gradient × A = 12 × 1.5 × 10⁻⁷ = 1.8 × 10⁻⁶ Ω m. Mark scheme (2 marks). C1: ρ = gradient × A. A1: ρ = 1.8 × 10⁻⁶ Ω m.', 2, NULL, NULL),
('0ff47131-d53e-5e0c-ba41-3ef4ee19f230', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 13, 13, 'How should a best-fit straight line be drawn through plotted points?', NULL, 1, 'multiple_choice'::answer_type, 'With the points scattered about evenly on either side of it', NULL, false, NULL, false, NULL, 'It need not pass through any particular point. Mark scheme (1 mark). B1: D (With the points scattered about evenly on either side of it).', 1, NULL, NULL),
('21c4dbdb-b5bf-5faa-897c-cd47e1c6e3f7', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 14, 14, 'Calculate lg 250, to three decimal places.', NULL, 1, 'numeric'::answer_type, '2.398', NULL, false, NULL, false, NULL, 'Using the calculator log key: lg 250 = 2.398. Check: 10 raised to this power returns 250. Mark scheme (1 mark). A1: lg 250 = 2.398.', 1, NULL, NULL),
('23dae558-ee39-5c9c-a768-cf3874303e17', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 15, 15, 'Which choice of scales on a graph is best?', NULL, 1, 'multiple_choice'::answer_type, 'Scales that make the plotted points occupy more than half of the grid in each direction', NULL, false, NULL, false, NULL, 'Large, simple scales make plotting and reading accurate. Mark scheme (1 mark). B1: B (Scales that make the plotted points occupy more than half of the grid in each direction).', 1, NULL, NULL),
('8cc216ec-690e-58ef-af42-677bdad8d61a', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 16, 16, 'A graph of V against I for a resistor is a straight line through the origin with gradient 47 V A⁻¹. State the resistance.', NULL, 1, 'numeric'::answer_type, '47', 'Ω', false, NULL, false, NULL, 'R = V/I = gradient = 47 × 1 = 47 Ω. Mark scheme (2 marks). C1: R = gradient. A1: R = 47 Ω.', 2, NULL, NULL),
('88a5b7df-5bd3-55e9-b522-f10b412c9ec0', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 17, 17, 'A graph of terminal p.d. V against current I for a cell is a straight line, V = E − Ir. What does the intercept on the V axis give?', NULL, 1, 'multiple_choice'::answer_type, 'The e.m.f. E', NULL, false, NULL, false, NULL, 'When I = 0 there are no lost volts, so V = E. Mark scheme (1 mark). B1: C (The e.m.f. E).', 1, NULL, NULL),
('c5ebb784-35b6-50a3-954f-c19fd3f16f53', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 18, 18, 'For a cell, V = E − Ir. A graph of V against I has gradient −0.80 V A⁻¹. Find the internal resistance.', NULL, 1, 'numeric'::answer_type, '0.8', 'Ω', false, NULL, false, NULL, 'Gradient = −r, so r = −(−0.80) = 0.80 Ω. Mark scheme (2 marks). C1: gradient = −r. A1: r = 0.80 Ω.', 2, NULL, NULL),
('ead12c3e-d0c0-55fc-9f53-e178dcd50c06', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 19, 19, 'One plotted point lies far from an otherwise clear straight-line trend. What should be done?', NULL, 1, 'multiple_choice'::answer_type, 'Check or repeat that reading; if it is still anomalous, ignore it when drawing the line', NULL, false, NULL, false, NULL, 'Anomalous points should not distort the best-fit line. Mark scheme (1 mark). B1: A (Check or repeat that reading; if it is still anomalous, ignore it when drawing the line).', 1, NULL, NULL),
('5153bf1e-8275-531a-9a91-23d821745d80', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 20, 20, 'Calculate ln 20.0, to three significant figures.', NULL, 1, 'numeric'::answer_type, '2.996', NULL, false, NULL, false, NULL, 'Using the calculator ln key: ln 20.0 = 3.00. Check: e raised to this power returns 20.0. Mark scheme (1 mark). A1: ln 20.0 = 3.00.', 1, NULL, NULL),
('43ea488f-6574-5e54-be1f-77315165134e', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 21, 21, 'Why is the mean of several repeated readings used?', NULL, 1, 'multiple_choice'::answer_type, 'It reduces the effect of random errors', NULL, false, NULL, false, NULL, 'Random errors scatter either side of the true value and partly cancel. Mark scheme (1 mark). B1: D (It reduces the effect of random errors).', 1, NULL, NULL),
('c9e4324a-251c-54cf-905e-c85ba909e39c', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 22, 22, 'Four repeat timings are 2.42 s, 2.38 s, 2.46 s and 2.40 s. Calculate the mean.', NULL, 1, 'numeric'::answer_type, '2.415', 's', false, NULL, false, NULL, 'Mean = (2.42 + 2.38 + 2.46 + 2.40) ÷ 4 = 2.42 s. Mark scheme (2 marks). C1: sum ÷ 4. A1: mean = 2.42 s.', 2, NULL, NULL),
('4c0d26fd-3b4f-5120-96cd-1a01a4ef1f57', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 23, 23, 'A graph of current I against p.d. V for a resistor is a straight line through the origin with gradient 0.020 A V⁻¹. Calculate the resistance.', NULL, 1, 'numeric'::answer_type, '50', 'Ω', false, NULL, false, NULL, 'Gradient = I/V = 1/R, so R = 1 ÷ 0.020 = 50 Ω. Mark scheme (2 marks). C1: gradient = 1/R. A1: R = 50 Ω.', 2, NULL, NULL),
('d09b117f-0140-5994-96a9-b130c2cfe740', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 24, 24, 'When y values are recorded to 3 significant figures, how many decimal places should values of lg y be given to?', NULL, 1, 'multiple_choice'::answer_type, '3 decimal places', NULL, false, NULL, false, NULL, 'The decimal places of a logarithm match the significant figures of the data. Mark scheme (1 mark). B1: B (3 decimal places).', 1, NULL, NULL),
('eb040d0a-bdfb-5c16-976c-aabecfb9e1fd', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 25, 25, 'A student plots T² against L for a pendulum and obtains a gradient of 4.02 s² m⁻¹. Calculate g, using T = 2π√(L/g).', NULL, 2, 'numeric'::answer_type, '9.821', 'm s⁻²', false, NULL, false, NULL, 'Gradient = 4π²/g, so g = 4π² ÷ 4.02 = 9.82 m s⁻². Mark scheme (3 marks). C1: gradient = 4π²/g. C1: rearranged. A1: g = 9.82 m s⁻².', 3, NULL, NULL),
('083ab24d-72e0-5b2c-8de9-37ebdba145a2', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 26, 26, 'A graph of charge Q against p.d. V for a capacitor has gradient 4.7 × 10⁻⁴ C V⁻¹. Calculate the capacitance in µF.', NULL, 2, 'numeric'::answer_type, '470', 'µF', false, NULL, false, ARRAY['4.7e-4']::text[], 'C = gradient = 4.7 × 10⁻⁴ F. In µF: 4.7 × 10⁻⁴ × 10⁶ = 470. Mark scheme (3 marks). C1: C = Q/V = gradient. C1: µF. A1: C = 470 µF.', 3, NULL, NULL),
('7ffadb10-75f7-563d-acfa-05875044b767', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 27, 27, 'In a photoelectric experiment, a graph of stopping voltage V against frequency f has gradient 4.1 × 10⁻¹⁵ V s. Calculate the Planck constant, in units of 10⁻³⁴ J s. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '6.56', '10⁻³⁴ J s', false, NULL, false, NULL, 'eV = hf − Φ, so gradient = h/e and h = 1.60 × 10⁻¹⁹ × 4.1 × 10⁻¹⁵ = 6.56 × 10⁻³⁴ J s. Mark scheme (3 marks). C1: gradient = h/e. C1: h = e × gradient. A1: h = 6.56 × 10⁻³⁴ J s.', 3, NULL, NULL),
('86488bf0-a4f7-567a-994b-faff67462ea4', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 28, 28, 'A graph of stopping voltage against frequency has gradient 4.1 × 10⁻¹⁵ V s and meets the frequency axis at 5.5 × 10¹⁴ Hz. Calculate the work function in eV.', NULL, 2, 'numeric'::answer_type, '2.255', 'eV', false, NULL, false, NULL, 'Φ/e = gradient × f₀ = 4.1 × 10⁻¹⁵ × 5.5 × 10¹⁴ = 2.26 V, so Φ = 2.26 eV. Mark scheme (3 marks). C1: threshold frequency. C1: Φ = hf₀. A1: Φ = 2.26 eV.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fgb1b365e8-t fgb1b365e8-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgb1b365e8-t">Stopping voltage against frequency</title><desc id="fgb1b365e8-d">A straight line on a graph of stopping voltage against frequency, starting on the frequency axis at 5.5 × 10¹⁴ Hz and rising with gradient 4.1 × 10⁻¹⁵ V s.</desc><line x1="24" y1="34" x2="24" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="83.7" y1="34" x2="83.7" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="143.3" y1="34" x2="143.3" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="203" y1="34" x2="203" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="262.7" y1="34" x2="262.7" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="322.3" y1="34" x2="322.3" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="172.7" x2="382" y2="172.7" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="103.3" x2="382" y2="103.3" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="34" x2="382" y2="34" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="242" x2="388" y2="242" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="242" x2="24" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,242 385.7,245 385.7,239" style="fill:currentColor;stroke:none"/><polygon points="24,24 27,30.3 21,30.3" style="fill:currentColor;stroke:none"/><line x1="24" y1="242" x2="24" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="24" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="83.7" y1="242" x2="83.7" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="83.7" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2</text><line x1="143.3" y1="242" x2="143.3" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="143.3" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4</text><line x1="203" y1="242" x2="203" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="203" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">6</text><line x1="262.7" y1="242" x2="262.7" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="262.7" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">8</text><line x1="322.3" y1="242" x2="322.3" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="322.3" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">10</text><line x1="382" y1="242" x2="382" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="382" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">12</text><line x1="20" y1="242" x2="24" y2="242" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="242" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="20" y1="172.7" x2="24" y2="172.7" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="172.7" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">1</text><line x1="20" y1="103.3" x2="24" y2="103.3" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="103.3" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">2</text><line x1="20" y1="34" x2="24" y2="34" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="34" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">3</text><text x="203" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">f / 10¹⁴ Hz</text><text x="20" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">stopping voltage / V</text><polyline points="188.1,242 382,57.2" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="188.1" y="230" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">f₀</text></svg>', 'A straight line on a graph of stopping voltage against frequency, starting on the frequency axis at 5.5 × 10¹⁴ Hz and rising with gradient 4.1 × 10⁻¹⁵ V s.'),
('4f212f40-5020-5ad2-8b52-f9e4c5307929', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 29, 29, 'To test y = kx², a student plots y against x². The best-fit line passes through (4.0, 10.2) and (36.0, 90.6). Calculate k.', NULL, 2, 'numeric'::answer_type, '2.512', NULL, false, NULL, false, NULL, 'k = gradient = (90.6 − 10.2) ÷ (36.0 − 4.0) = 2.51. Mark scheme (4 marks). M1: k is the gradient. C1: Δy. C1: Δx. A1: k = 2.51.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fgfc337376-t fgfc337376-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgfc337376-t">y against x²</title><desc id="fgfc337376-d">A best-fit line on a graph of y against x² through (4.0, 10.2) and (36.0, 90.6).</desc><line x1="36.2" y1="34" x2="36.2" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="122.6" y1="34" x2="122.6" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209.1" y1="34" x2="209.1" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="295.5" y1="34" x2="295.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="200.4" x2="382" y2="200.4" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-lin