('8f81ea58-133d-5bde-8733-1cf1e3053f9e', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 33, 33, 'For a capacitor discharging through a resistor, a graph of ln V against t has gradient −0.025 s⁻¹. Calculate the time constant.', NULL, 2, 'numeric'::answer_type, '40', 's', false, NULL, false, NULL, 'Gradient = −1/RC, so RC = 1 ÷ 0.025 = 40 s. Mark scheme (3 marks). C1: gradient = −1/RC. C1: value. A1: RC = 40 s.', 3, NULL, NULL),
('9853c823-5e06-549c-a7b2-8f5bbfe0cfb8', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 34, 34, 'A graph of lg(T/s) against lg(L/m) has gradient 0.48 and intercept 0.30. Predict T for L = 0.64 m.', NULL, 2, 'numeric'::answer_type, '1.611', 's', false, NULL, false, NULL, 'T = 10^0.30 × 0.64^0.48 = 1.61 s. Mark scheme (3 marks). C1: k = 10^0.30. C1: T = kLⁿ. A1: T = 1.61 s.', 3, NULL, NULL),
('dfd80875-28db-52b1-a3e1-cfd8ab8e9ce1', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 35, 35, 'Why is it better to plot T² against L than T against L for a pendulum?', NULL, 2, 'multiple_choice'::answer_type, 'T² ∝ L gives a straight line through the origin, so g can be found from the gradient', NULL, false, NULL, false, NULL, 'Linearising lets the constant be found from a gradient. Mark scheme (3 marks). C1: straight line. C1: constant from gradient. A1: A (T² ∝ L gives a straight line through the origin, so g can be found from the gradient).', 3, NULL, NULL),
('42aa276d-9079-5071-8aa9-0d08bcf0d634', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 36, 36, 'A graph of pressure p against 1/V for 0.10 mol of gas has gradient 250 Pa m³. Calculate the temperature of the gas. Take R = 8.31 J K⁻¹ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '300.8', 'K', false, NULL, false, NULL, 'pV = nRT, so gradient = nRT and T = 250 ÷ (0.10 × 8.31) = 301 K. Mark scheme (3 marks). C1: gradient = nRT. C1: rearranged. A1: T = 301 K.', 3, NULL, NULL),
('984afd34-b01c-56a5-a473-55ce91292c19', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 37, 37, 'A graph of ln(activity) against time has gradient −0.0231 min⁻¹. Calculate the half-life, in minutes.', NULL, 2, 'numeric'::answer_type, '30.01', 'min', false, NULL, false, NULL, 'λ = 0.0231 min⁻¹; t½ = ln 2 ÷ 0.0231 = 30.0 min. Mark scheme (3 marks). C1: λ = −gradient. C1: t½ = ln 2/λ. A1: t½ = 30.0 min.', 3, NULL, NULL),
('fd163e0b-d70f-532c-8f03-b63360e75827', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 38, 38, 'For a diffraction grating, a graph of sin θ against order n has gradient 0.295. The slit spacing is 2.0 µm. Calculate the wavelength in nm.', NULL, 2, 'numeric'::answer_type, '590 nm', 'nm', false, NULL, false, NULL, 'd sin θ = nλ, so gradient = λ/d and λ = 0.295 × 2.0 × 10⁻⁶ = 5.90 × 10⁻⁷ m. In nm: 5.90 × 10⁻⁷ × 10⁹ = 590. Mark scheme (4 marks). M1: gradient = λ/d. C1: substitution. C1: nm. A1: λ = 590 nm.', 4, NULL, NULL),
('dac1f2be-b91e-560a-b3a8-6b5e70d2a1d0', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 39, 39, 'How large should the triangle used to measure a gradient be?', NULL, 2, 'multiple_choice'::answer_type, 'As large as possible, with its hypotenuse covering more than half the length of the line', NULL, false, NULL, false, NULL, 'A large triangle reduces the relative reading error. Mark scheme (3 marks). C1: large triangle. C1: more than half the line. A1: D (As large as possible, with its hypotenuse covering more than half the length of the line).', 3, NULL, NULL),
('9ac9b8df-8055-586c-99b2-9ff8a627919c', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', 'ce473f5f-8864-4efe-be59-be54ed9c0caa', 'a-level', 'P2.3', '9702 coursebook P2.3 · Analysis of the data', 40, 40, 'A graph of resistance R against temperature θ for a wire is a straight line, R = R₀(1 + αθ), with intercept 20.0 Ω and gradient 0.078 Ω K⁻¹. Calculate α, in units of 10⁻³ K⁻¹.', NULL, 2, 'numeric'::answer_type, '3.9', '10⁻³ K⁻¹', false, NULL, false, NULL, 'Gradient = R₀α, so α = 0.078 ÷ 20.0 = 0.00390 K⁻¹. Mark scheme (3 marks). C1: gradient = R₀α. C1: intercept = R₀. A1: α = 3.9 × 10⁻³ K⁻¹.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg22dac885-t fg22dac885-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg22dac885-t">Resistance against temperature</title><desc id="fg22dac885-d">A straight line on a graph of R against θ, crossing the R axis at 20.0 Ω with gradient 0.078 Ω K⁻¹.</desc><line x1="29.4" y1="34" x2="29.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="100" y1="34" x2="100" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="170.5" y1="34" x2="170.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="241" y1="34" x2="241" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="311.5" y1="34" x2="311.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="382" y2="242" st