ext-anchor="middle" dominant-baseline="central" style="fill:currentColor">60</text><line x1="311.5" y1="242" x2="311.5" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="311.5" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">80</text><line x1="382" y1="242" x2="382" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="382" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">100</text><line x1="25.4" y1="242" x2="29.4" y2="242" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="242" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="25.4" y1="172.7" x2="29.4" y2="172.7" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="172.7" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">10</text><line x1="25.4" y1="103.3" x2="29.4" y2="103.3" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="103.3" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">20</text><line x1="25.4" y1="34" x2="29.4" y2="34" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="22.4" y="34" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">30</text><text x="205.7" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">θ / °C</text><text x="25.4" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">R / Ω</text><polyline points="29.4,103.3 382,49.3" style="stroke:var(--fig-accent,#1d4ed8);s