('af773758-ee41-59bf-a06a-0a1ac3037d94', '88a5b7df-5bd3-55e9-b522-f10b412c9ec0', 'The external resistance', 'D', false, 3),
('117c58fe-0eba-544c-9879-b2d1dcb8a550', 'ead12c3e-d0c0-55fc-9f53-e178dcd50c06', 'Check or repeat that reading; if it is still anomalous, ignore it when drawing the line', 'A', true, 0),
('1dc4e559-d5e3-5520-9ab5-7d443ab588ce', 'ead12c3e-d0c0-55fc-9f53-e178dcd50c06', 'Draw the line through it', 'B', false, 1),
('5dc7e3d1-5f8d-5679-803f-a61a4c7921f2', 'ead12c3e-d0c0-55fc-9f53-e178dcd50c06', 'Delete all the readings', 'C', false, 2),
