('3a064b5f-0a61-5aa8-a561-e5085dea4485', '43ea488f-6574-5e54-be1f-77315165134e', 'It removes systematic errors', 'A', false, 0),
('2f202524-8af8-5894-890a-083fd946ab89', '43ea488f-6574-5e54-be1f-77315165134e', 'It makes the reading more accurate whatever the error', 'B', false, 1),
