('d944b1ad-f98c-5595-9660-5e06ae65f25d', 'd09b117f-0140-5994-96a9-b130c2cfe740', '3 significant figures', 'C', false, 2),
('5cfe03cb-4ca9-577b-ab30-ea9311360941', 'd09b117f-0140-5994-96a9-b130c2cfe740', 'As many as the calculator shows', 'D', false, 3),
('d842c651-44a7-5976-a9e6-4fb317e82dd2', '2202f154-72c3-54a7-84d3-fe1f339b3673', 'Measure the gradient at the origin', 'A', false, 0),
('de86dfb5-7e7f-5856-baa7-80bd7ae3abb3', '2202f154-72c3-54a7-84d3-fe1f339b3673', 'Plot y against x again with a larger scale', 'B', false, 1),
('8d3e5457-d5e4-5cf6-a316-abfb53c59d86', '2202f154-72c3-54a7-84d3-fe1f339b3673', 'Plot lg y against lg x and see whether the gradient is 2 or 3', 'C', true, 2),
('0484af53-a73d-513b-b1e0-2a9d473e37e2', '2202f154-72c3-54a7-84d3-fe1f339b3673', 'Find the mean of y', 'D', false, 3),
('1f3bb509-711f-514e-9d89-1493821f658a', 'dfd80875-28db-52b1-a3e1-cfd8ab8e9ce1', 'T² ∝ L gives a straight line through the origin, so g can be found from the gradient', 'A', true, 0),
('acf5d620-076d-5e49-b37a-3d6b45702827', 'dfd80875-28db-52b1-a3e1-cfd8ab8e9ce1', 'T against L is a straight line', 'B', false, 1),
('984dac26-2039-5b63-936f-c5ba2b86f213', 'dfd80875-28db-52b1-a3e1-cfd8ab8e9ce1', 'It reduces the uncertainty in L', 'C', false, 2),
('3e4902db-b6e5-5489-89e3-32dd02780c24', 'dfd80875-28db-52b1-a3e1-cfd8ab8e9ce1', 'It avoids measuring T', 'D', false, 3),
