INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('e10352d6-05ce-5ae2-add3-fbbfe29fb65a', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 7, 7, 'A supply is labelled 12.0 V ± 2.5%. Calculate the absolute uncertainty in its voltage.', NULL, 1, 'numeric'::answer_type, '0.3', 'V', false, NULL, false, NULL, 'ΔV = 2.5 ÷ 100 × 12.0 = 0.30 V. Mark scheme (2 marks). C1: % × value. A1: ΔV = 0.30 V.', 2, NULL, NULL),
('97c4b2e8-8cef-5bbd-be39-a9a85bde095c', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 8, 8, 'A length is measured as 25.0 ± 0.5 cm. Calculate its percentage uncertainty.', NULL, 1, 'numeric'::answer_type, '2', '%', false, NULL, false, NULL, '% uncertainty = 0.5 ÷ 25.0 × 100 = 2.0 %. Mark scheme (2 marks). C1: absolute ÷ value × 100. A1: % uncertainty = 2.0%.', 2, NULL, NULL),
('56938419-8f8f-5d04-a4f5-42ebabf85d6d', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 9, 9, 'Two lengths, 12.4 ± 0.2 cm and 3.6 ± 0.1 cm, are added. Calculate the absolute uncertainty of the total, in cm.', NULL, 1, 'numeric'::answer_type, '0.3 cm', 'cm', false, NULL, false, NULL, 'For a sum, add absolute uncertainties: 0.2 + 0.1 = 0.3 cm. Mark scheme (2 marks). C1: add absolute uncertainties. A1: Δ = 0.3 cm.', 2, NULL, NULL),
('9d1533ff-3ac0-541a-911a-d46f7aab8071', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 10, 10, 'The ends of a spring are at 85.2 ± 0.1 cm and 12.7 ± 0.1 cm on a rule. Calculate the absolute uncertainty in the length of the spring, in cm.', NULL, 1, 'numeric'::answer_type, '0.2 cm', 'cm', false, NULL, false, NULL, 'For a difference, the absolute uncertainties still add: 0.1 + 0.1 = 0.2 cm. Mark scheme (2 marks). C1: add for a difference. A1: Δ = 0.2 cm.', 2, NULL, NULL),
('3ea845b0-dcc4-52a3-a215-17bbcd887456', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 11, 11, 'A resistance is found from R = V/I, with V uncertain by 2.0% and I by 1.5%. Calculate the percentage uncertainty in R.', NULL, 1, 'numeric'::answer_type, '3.5', '%', false, NULL, false, NULL, '% in R = 2.0 + 1.5 = 3.5 %. Mark scheme (2 marks). C1: add percentages for a quotient. A1: % uncertainty = 3.5%.', 2, NULL, NULL),
('9fe489c2-a03b-5583-a9f8-f5dd448631cf', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 12, 12, 'A speed v has a percentage uncertainty of 1.5%. Calculate the percentage uncertainty in v².', NULL, 1, 'numeric'::answer_type, '3', '%', false, NULL, false, NULL, '% in v² = 2 × 1.5 = 3.0 %. Mark scheme (2 marks). C1: power × %. A1: % uncertainty = 3.0%.', 2, NULL, NULL),
('7d811b85-9214-5d4e-a27a-17b3279bba30', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 13, 13, 'How is the uncertainty in a set of repeated readings usually estimated?', NULL, 1, 'multiple_choice'::answer_type, 'Half the range of the readings', NULL, false, NULL, false, NULL, 'Half of (largest − smallest) covers the spread either side of the mean. Mark scheme (1 mark). B1: C (Half the range of the readings).', 1, NULL, NULL),
('9cea6ea0-0988-5f23-ab16-9c774a9bcf6f', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 14, 14, 'Repeat readings of a diameter are 3.42, 3.48, 3.45 and 3.39 mm. Estimate the uncertainty as half the range, in mm.', NULL, 1, 'numeric'::answer_type, '0.045 mm', 'mm', false, NULL, false, NULL, 'Uncertainty = (3.48 − 3.39) ÷ 2 = 0.045 mm. Mark scheme (2 marks). C1: half the range. A1: Δd = 0.045 mm.', 2, NULL, NULL),
('0450bc14-b49c-5661-b531-a101747d72f2', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 15, 15, 'What does the length of an error bar on a graph represent?', NULL, 1, 'multiple_choice'::answer_type, 'The absolute uncertainty in the plotted value, drawn above and below (or either side of) the point', NULL, false, NULL, false, NULL, 'Each bar extends ± the absolute uncertainty. Mark scheme (1 mark). B1: A (The absolute uncertainty in the plotted value, drawn above and below (or either side of) the point).', 1, NULL, NULL),
('e3661c6c-a0e1-5eee-b05a-90096e28547c', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 16, 16, 'What is the "worst acceptable line" on a graph with error bars?', NULL, 1, 'multiple_choice'::answer_type, 'The steepest or shallowest straight line that still passes through all the error bars', NULL, false, NULL, false, NULL, 'Its gradient is used to estimate the uncertainty in the gradient. Mark scheme (1 mark). B1: D (The steepest or shallowest straight line that still passes through all the error bars).', 1, NULL, NULL),
('7900c45f-a95f-5e4f-92b4-5d0f6a2e8840', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 17, 17, 'A length of 45 mm is read on a rule with each end uncertain by ±0.5 mm. Calculate the percentage uncertainty in the length.', NULL, 1, 'numeric'::answer_type, '2.222', '%', false, NULL, false, NULL, 'Δ = 0.5 + 0.5 = 1.0 mm; % = 1.0 ÷ 45 × 100 = 2.2 %. Mark scheme (2 marks). C1: two readings, add. A1: % uncertainty = 2.2%.', 2, NULL, NULL),
('11ddc67e-f262-56a6-9883-925d2cfc1307', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 18, 18, 'A meter reads 0.02 A when no current flows. What type of error does this cause in every reading?', NULL, 1, 'multiple_choice'::answer_type, 'A systematic (zero) error', NULL, false, NULL, false, NULL, 'It shifts all readings by the same amount. Mark scheme (1 mark). B1: B (A systematic (zero) error).', 1, NULL, NULL),
('db5f972a-71bd-501c-be00-78b544c1dfbe', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 19, 19, 'Ten oscillations take 15.3 s with a reaction-time uncertainty of ±0.1 s. Calculate the percentage uncertainty in the period.', NULL, 1, 'numeric'::answer_type, '0.6536', '%', false, NULL, false, NULL, '% = 0.1 ÷ 15.3 × 100 = 0.65 %. Mark scheme (2 marks). C1: same % as total time. A1: % uncertainty = 0.65%.', 2, NULL, NULL),
('67a04f69-2717-569f-9a6b-8ea51fc1bbd1', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 20, 20, 'A value y = 50 ± 5 is to be plotted as lg y. How is the error bar for lg y found?', NULL, 1, 'multiple_choice'::answer_type, 'Calculate lg(55) − lg(50) (or lg 50 − lg 45)', NULL, false, NULL, false, NULL, 'The bar is the change in lg y caused by the uncertainty in y. Mark scheme (1 mark). B1: C (Calculate lg(55) − lg(50) (or lg 50 − lg 45)).', 1, NULL, NULL),
('9930aa5a-fa3f-5b86-b2ac-576dfce669e3', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 21, 21, 'A quantity y = 50 ± 5. Calculate the uncertainty in lg y using lg(y + Δy) − lg y.', NULL, 1, 'numeric'::answer_type, '0.04139', NULL, false, NULL, false, NULL, 'Δ(lg y) = lg 55 − lg 50 = 0.041. Mark scheme (2 marks). C1: difference of logs. A1: Δ(lg y) = 0.041.', 2, NULL, NULL),
('6b984c20-e49b-5fb2-bc3a-28d864b4e048', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 22, 22, 'Three readings of a current are 0.52 A, 0.55 A and 0.49 A. Estimate the uncertainty in the mean as half the range.', NULL, 1, 'numeric'::answer_type, '0.03', 'A', false, NULL, false, NULL, 'Uncertainty = (0.55 − 0.49) ÷ 2 = 0.03 A. Mark scheme (2 marks). C1: half the range. A1: ΔI = 0.03 A.', 2, NULL, NULL),
('ab579fc2-13ed-56c4-bab7-f3cb7c553f38', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 23, 23, 'Which statement describes precise readings?', NULL, 1, 'multiple_choice'::answer_type, 'Repeated readings that are close to each other', NULL, false, NULL, false, NULL, 'Precision is about spread; accuracy is closeness to the true value. Mark scheme (1 mark). B1: A (Repeated readings that are close to each other).', 1, NULL, NULL),
('4816536b-46cb-577b-b490-ec09b19a1b13', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 24, 24, 'A length is 2.50 ± 0.02 m. Calculate its percentage uncertainty.', NULL, 1, 'numeric'::answer_type, '0.8', '%', false, NULL, false, NULL, '% = 0.02 ÷ 2.50 × 100 = 0.8 %. Mark scheme (1 mark). A1: % uncertainty = 0.8%.', 1, NULL, NULL),
('eefca5d9-3fae-5481-9d5d-cb72140b2780', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 25, 25, 'The volume of a cylinder is V = πd²L/4. The diameter has an uncertainty of 2.0% and the length 1.0%. Calculate the percentage uncertainty in V.', NULL, 2, 'numeric'::answer_type, '5', '%', false, NULL, false, NULL, '% in V = 2 × 2.0 + 1.0 = 5.0 %. Mark scheme (3 marks). C1: d² doubles its %. C1: add L. A1: % uncertainty = 5.0%.', 3, NULL, NULL),
('1565f644-424d-5ab8-ab59-4cbccd3d8805', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 26, 26, 'g is found from g = 4π²L/T². L is uncertain by 0.5% and T by 1.0%. Calculate the percentage uncertainty in g.', NULL, 2, 'numeric'::answer_type, '2.5', '%', false, NULL, false, NULL, '% in g = 0.5 + 2 × 1.0 = 2.5 %. Mark scheme (3 marks). C1: T² doubles. C1: sum. A1: % uncertainty = 2.5%.', 3, NULL, NULL),
('9649e8b7-0e56-5250-9de3-f09c48e018a6', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 27, 27, 'Density is found from ρ = m/(πr²h). The uncertainties are 1.0% in m, 2.0% in r and 0.5% in h. Calculate the percentage uncertainty in ρ.', NULL, 2, 'numeric'::answer_type, '5.5', '%', false, NULL, false, NULL, '% in ρ = 1.0 + 2 × 2.0 + 0.5 = 5.5 %. Mark scheme (3 marks). C1: r² term. C1: total. A1: % uncertainty = 5.5%.', 3, NULL, NULL),
('266e54c0-3cd2-571c-9d01-73a8af5f7174', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 28, 28, 'The best-fit line on a graph has gradient 4.20 and the worst acceptable line has gradient 4.55. Calculate the absolute uncertainty in the gradient.', NULL, 2, 'numeric'::answer_type, '0.35', NULL, false, NULL, false, NULL, 'Δm = 4.55 − 4.20 = 0.35. Mark scheme (3 marks). C1: worst − best. C1: value. A1: Δm = 0.35.', 3, NULL, NULL),
('4396b0b6-f311-5bc9-9e6b-d3d29bcd12f7', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 29, 29, 'A best-fit gradient is 2.50 and the worst acceptable gradient is 2.70. Calculate the percentage uncertainty in the gradient.', NULL, 2, 'numeric'::answer_type, '8', '%', false, NULL, false, NULL, '% = (2.70 − 2.50) ÷ 2.50 × 100 = 8.0 %. Mark scheme (3 marks). C1: absolute uncertainty. C1: percentage. A1: % uncertainty = 8.0%.', 3, NULL, NULL),
('8a4e0518-9c4d-554d-ace6-263b8ed2fada', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 30, 30, 'The best-fit line has a y-intercept of 0.60 and the worst acceptable line one of 0.45. State the uncertainty in the y-intercept.', NULL, 2, 'numeric'::answer_type, '0.15', NULL, false, NULL, false, NULL, 'Δc = 0.60 − 0.45 = 0.15. Mark scheme (3 marks). C1: difference of intercepts. C1: value. A1: Δc = 0.15.', 3, NULL, NULL),
('066657d5-ae01-5166-ab7e-c3f999c3e89a', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 31, 31, 'A spring constant is found from k = 4π²/m, where m = 0.160 ± 0.008 s² kg⁻¹ is the gradient of T² against mass. Calculate k and its absolute uncertainty. Give only the uncertainty, in N m⁻¹.', NULL, 2, 'numeric'::answer_type, '12.34', 'N m⁻¹', false, 0.05, false, NULL, 'k = 4π² ÷ 0.160 = 246.7 N m⁻¹; % = 0.008 ÷ 0.160 × 100 = 5.0 %; Δk = 0.050 × 246.7 = 12 N m⁻¹. Mark scheme (4 marks). C1: k. C1: % in gradient = % in k. C1: absolute. A1: Δk = 12 N m⁻¹.', 4, NULL, NULL),
('6d4088e3-d692-5af5-86ef-eed3b55ec239', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 32, 32, 'A speed is found from v = √(2gh). The height h has a 4.0% uncertainty. Calculate the percentage uncertainty in v.', NULL, 2, 'numeric'::answer_type, '2', '%', false, NULL, false, NULL, '% in v = 0.5 × 4.0 = 2.0 %. Mark scheme (3 marks). C1: power ½. C1: value. A1: % uncertainty = 2.0%.', 3, NULL, NULL),
('8bec42e5-d3a5-5ec2-a27e-3cfb117f5c96', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 33, 33, 'To find a resistivity a student uses ρ = πd²R/(4L), with R known to 2.0%, d to 1.5% and L to 0.2%. What is the percentage uncertainty in ρ?', NULL, 2, 'numeric'::answer_type, '5.2', '%', false, NULL, false, NULL, '% in ρ = 2.0 + 2 × 1.5 + 0.2 = 5.2 %. Mark scheme (3 marks). C1: d² term. C1: total. A1: % uncertainty = 5.2%.', 3, NULL, NULL),
('a12885c7-4ab8-50e8-938b-c6c76e9cd4fe', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 34, 34, 'A resistivity of 4.9 × 10⁻⁷ Ω m has an uncertainty of 5.2%. Calculate the absolute uncertainty, in units of 10⁻⁷ Ω m.', NULL, 2, 'numeric'::answer_type, '0.2548', '10⁻⁷ Ω m', false, 0.05, false, NULL, 'Δρ = 0.052 × 4.9 × 10⁻⁷ = 2.5 × 10⁻⁸ Ω m. Mark scheme (3 marks). C1: fraction × value. C1: units. A1: Δρ = 0.25 × 10⁻⁷ Ω m.', 3, NULL, NULL),
('d47b1086-c50a-51b0-9f9a-7ffb774bf084', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 35, 35, 'A value x = 2.0 ± 0.1 is plotted as lg x. Calculate the uncertainty in lg x.', NULL, 2, 'numeric'::answer_type, '0.02119', NULL, false, NULL, false, NULL, 'Δ(lg x) = lg 2.1 − lg 2.0 = 0.021. Mark scheme (3 marks). C1: lg of upper value. C1: difference. A1: Δ(lg x) = 0.021.', 3, NULL, NULL),
('d190b11d-9800-5028-990e-4bfa09b93159', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 36, 36, 'A time t = 40 ± 2 s is plotted as ln(t/s). Calculate the uncertainty in ln t.', NULL, 2, 'numeric'::answer_type, '0.04879', NULL, false, NULL, false, NULL, 'Δ(ln t) = ln 42 − ln 40 = 0.049. Mark scheme (3 marks). C1: ln of upper value. C1: difference. A1: Δ(ln t) = 0.049.', 3, NULL, NULL),
('ff0e6bd1-9ddc-57cf-94a0-114872bf83da', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 37, 37, 'An object distance u = 25.0 ± 0.5 cm is plotted as 1/u. Calculate the absolute uncertainty in 1/u, in units of 10⁻³ cm⁻¹.', NULL, 2, 'numeric'::answer_type, '816.3', '10⁻³ cm⁻¹', false, NULL, false, NULL, 'Δ(1/u) = 1 ÷ 24.5 − 1 ÷ 25.0 = 8.16 × 10⁻⁴ cm⁻¹. In units of 10⁻³ cm⁻¹: 8.16 × 10⁻⁴ × 10³ = 0.816. Mark scheme (3 marks). C1: 1/(u − Δu). C1: difference. A1: Δ(1/u) = 816 × 10⁻³ cm⁻¹.', 3, NULL, NULL),
('22f4bdea-c58f-5a68-8a32-fd72cd774d5d', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 38, 38, 'Ten oscillations take 15.6 ± 0.2 s. Calculate the absolute uncertainty in the period.', NULL, 2, 'numeric'::answer_type, '0.02', 's', false, NULL, false, NULL, 'ΔT = 0.2 ÷ 10 = 0.02 s. Mark scheme (3 marks). C1: divide uncertainty by 10. C1: value. A1: ΔT = 0.02 s.', 3, NULL, NULL),
('7019cd1f-413b-5880-b0ad-a5be532c4596', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 39, 39, 'How can the percentage uncertainty in measuring the thickness of a thin sheet of glass be reduced?', NULL, 2, 'multiple_choice'::answer_type, 'Use a micrometer rather than a ruler, and measure at several points to find a mean', NULL, false, NULL, false, NULL, 'A smaller instrument resolution and averaging both help. Mark scheme (3 marks). C1: higher-resolution instrument. C1: repeat and average. A1: D (Use a micrometer rather than a ruler, and measure at several points to find a mean).', 3, NULL, NULL),
('688fbe3c-09d7-519b-baa9-3be38fcb644a', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 40, 40, 'The side of a square sheet is 12.0 ± 0.1 cm. Calculate the absolute uncertainty in its area, in cm².', NULL, 2, 'numeric'::answer_type, '2.4', 'cm²', false, NULL, false, NULL, '% in side = 0.1 ÷ 12.0 × 100 = 0.833 %; % in area = 2 × 0.833 = 1.67 %; ΔA = 144 × 1.67 ÷ 100 = 2.4 cm². Mark scheme (3 marks). C1: double %. C1: absolute. A1: ΔA = 2.4 cm².', 3, NULL, NULL),
('c748ff40-ac6c-5f8f-a62f-53ac11add5f8', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 41, 41, 'Power is found from P = V²/R. V has a 2.0% uncertainty and R a 3.0% uncertainty. Calculate the percentage uncertainty in P.', NULL, 2, 'numeric'::answer_type, '7', '%', false, NULL, false, NULL, '% in P = 2 × 2.0 + 3.0 = 7.0 %. Mark scheme (3 marks). C1: V² term. C1: total. A1: % uncertainty = 7.0%.', 3, NULL, NULL),
('84f039e4-0ca5-5816-9c64-f9b350de96f7', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 42, 42, 'Kinetic energy is found from ½mv². m has an uncertainty of 0.5% and v = 4.0 ± 0.1 m s⁻¹. Calculate the percentage uncertainty in the kinetic energy.', NULL, 2, 'numeric'::answer_type, '5.5', '%', false, NULL, false, NULL, '% in v = 0.1 ÷ 4.0 × 100 = 2.5 %; % in E = 0.5 + 2 × 2.5 = 5.5 %. Mark scheme (4 marks). C1: % in v. M1: double for v². C1: add m. A1: % uncertainty = 5.5%.', 4, NULL, NULL),
('7ddd4551-6f02-571d-ac19-9f6162fc1ca8', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 43, 43, 'A pendulum has L = 0.800 ± 0.002 m and T = 1.80 ± 0.02 s. (a) Calculate g. (b) Calculate the percentage uncertainty in g. (c) Calculate the absolute uncertainty in g. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.241', 'm s⁻²', false, NULL, false, NULL, '(a) g = 4π² × 0.800 ÷ 1.80² = 9.748 m s⁻². (b) % = 0.25 + 2 × 1.11 = 2.47 %. (c) Δg = 2.47 ÷ 100 × 9.748 = 0.24 m s⁻². Mark scheme (5 marks). C1: g. C1: % in L. C1: 2 × % in T. M1: absolute = % × value. A1: Δg = 0.24 m s⁻².', 5, NULL, NULL),
('20c5c505-3e16-5660-a18a-448a46166543', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 44, 44, 'The Young modulus is found from E = 4FL/(πd²e). The uncertainties are 1.0% in F, 0.2% in L, 2.0% in d and 4.0% in e. (a) Explain why the uncertainty in d counts twice. (b) Calculate the percentage uncertainty in E.', NULL, 3, 'numeric'::answer_type, '9.2', '%', false, NULL, false, NULL, '(a) d is squared. (b) % in E = 1.0 + 0.2 + 2 × 2.0 + 4.0 = 9.2 %. Mark scheme (6 marks). B1: d² doubles its %. C1: F and L. C1: e. M1: sum of terms. C1: value. A1: % uncertainty = 9.2%.', 6, NULL, NULL),
('1f2ccf2a-a461-5dbe-a7a8-9c78eb95592a', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '88532559-c2d8-4be9-80c7-6275e8d6cf54', 'a-level', 'P2.4', '9702 coursebook P2.4 · Treatment of uncertainties', 45, 45, 'A graph with error bars has a best-fit gradient of 3.12. The worst acceptable line passes through (0.0, 0.60) and (5.0, 17.6). (a) Calculate the gradient of the worst acceptable line. (b) Calculate the percentage uncertainty in the gradient.', NULL, 3, 'numeric'::answer_type, '8.974', '%', false, NULL, false, NULL, '(a) m = (17.6 − 0.60) ÷ 5.0 = 3.40. (b) % = (3.40 − 3.12) ÷ 3.12 × 100 = 8.97 %. Mark scheme (5 marks). C1: worst gradient. M1: difference from best. C1: ÷ best. C1: value. A1: % uncertainty = 8.97%.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fgae3cfe02-t fgae3cfe02-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgae3cfe02-t">Best-fit and worst acceptable lines</title><desc id="fgae3cfe02-d">Five points with error bars; the best-fit line (gradient 3.12) and a steeper worst acceptable line from (0.0, 0.60) to (5.0, 17.6) that passes through every error bar.</desc><line x1="29.4" y1="34" x2="29.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93.5" y1="34" x2="93.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="157.6" y1="34" x2="157.6" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="221.7" y1="34" x2="221.7" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="285.8" y1="34" x2="285.8" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="349.9" y1="34" x2="349.9" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="190" x2="382" y2="190" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="138" x2="382" y2="138" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="86" x2="382" y2="86" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="34" x2="382" y2="34" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="388" y2="242" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="29.4" y1="242" x2="29.4" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,242 385.7,245 385.7,239" style="fill:currentColor;stroke:none"/><polygon points="29.4,24 32.4,30.3 26.5,30.3" style="fill:currentColor;stroke:none"/><line x1="29.4" y1="242" x2="29.4" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.4" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="93.5" y1="242" x2="93.5" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="93.5" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1</text><line x1="157.6" y1="242" x2="157.6" y2="246" style="stroke:currentColor;stroke-width:0.9;