INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('0b3dcbeb-c712-5f92-ba33-f21442f93ff4', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 7, 7, 'A class measures the speed of sound in air as 336 m s⁻¹; the accepted value is 343 m s⁻¹. By what percentage is the class value below the accepted one?', NULL, 1, 'numeric'::answer_type, '2.041', '%', false, NULL, false, NULL, '% = (343 − 336) ÷ 343 × 100 = 2.04 %. Mark scheme (2 marks). C1: difference ÷ accepted. A1: % difference = 2.04%.', 2, NULL, NULL),
('e615768f-7107-53df-b9ae-6446df83fae2', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 8, 8, 'A result is quoted as 4.2 ± 0.3. State the lowest value within its uncertainty.', NULL, 1, 'numeric'::answer_type, '3.9', NULL, false, NULL, false, NULL, 'Lower limit = 4.2 − 0.3 = 3.9. Mark scheme (2 marks). C1: value − uncertainty. A1: lower limit = 3.9.', 2, NULL, NULL),
('158b3f81-4efb-5d39-9be2-64a38a59ca26', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 9, 9, 'A measured value is 8.2 ± 0.5 and the accepted value is 8.5. Does the result agree with the accepted value?', NULL, 1, 'multiple_choice'::answer_type, 'Yes, because 8.5 lies between 7.7 and 8.7', NULL, false, NULL, false, NULL, 'Agreement means the accepted value lies within the range of the result. Mark scheme (1 mark). B1: C (Yes, because 8.5 lies between 7.7 and 8.7).', 1, NULL, NULL),
('b2b8eec9-7e6c-5392-a864-1c08670404fd', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 10, 10, 'An experiment gives 2.10 ± 0.05 for a constant whose textbook value is 2.30. What should the student conclude?', NULL, 1, 'multiple_choice'::answer_type, 'No, because 2.30 is outside the range 2.05 to 2.15', NULL, false, NULL, false, NULL, 'The accepted value must lie inside the range of the result. Mark scheme (1 mark). B1: A (No, because 2.30 is outside the range 2.05 to 2.15).', 1, NULL, NULL),
('f868511a-d0e5-577c-8c6c-5416a562a411', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 11, 11, 'In an evaluation, what is a limitation?', NULL, 1, 'multiple_choice'::answer_type, 'A problem with the procedure or apparatus that causes uncertainty in the results', NULL, false, NULL, false, NULL, 'Each limitation should be matched with an improvement. Mark scheme (1 mark). B1: D (A problem with the procedure or apparatus that causes uncertainty in the results).', 1, NULL, NULL),
('681c0153-ddad-5593-b2de-ffe858d0f7d5', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 12, 12, 'Reaction time makes hand-timing of a short fall unreliable. Which improvement is best?', NULL, 1, 'multiple_choice'::answer_type, 'Use light gates connected to an electronic timer', NULL, false, NULL, false, NULL, 'Electronic timing removes human reaction time. Mark scheme (1 mark). B1: B (Use light gates connected to an electronic timer).', 1, NULL, NULL),
('cc57df6d-0a56-5a27-b2b6-7341533d8120', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 13, 13, 'Readings of a pointer against a scale suffer from parallax. Which improvement is best?', NULL, 1, 'multiple_choice'::answer_type, 'Read with the eye level with the pointer, or use a mirror scale', NULL, false, NULL, false, NULL, 'Viewing perpendicular to the scale removes parallax. Mark scheme (1 mark). B1: C (Read with the eye level with the pointer, or use a mirror scale).', 1, NULL, NULL),
('ef994e03-7651-5ba6-a7e4-2b484f05da60', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 14, 14, 'A graph of y against x is a straight line through the origin, within the error bars. What is the conclusion?', NULL, 1, 'multiple_choice'::answer_type, 'y is proportional to x', NULL, false, NULL, false, NULL, 'A straight line through the origin shows direct proportion. Mark scheme (1 mark). B1: A (y is proportional to x).', 1, NULL, NULL),
('cbcf8dbf-65de-5bbc-aa71-1080caa12648', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 15, 15, 'A graph of y against x is a straight line with a positive intercept on the y-axis. What can be concluded?', NULL, 1, 'multiple_choice'::answer_type, 'y increases linearly with x but is not proportional to it', NULL, false, NULL, false, NULL, 'Proportionality requires the line to pass through the origin. Mark scheme (1 mark). B1: D (y increases linearly with x but is not proportional to it).', 1, NULL, NULL),
('529db7de-4be1-539e-95bb-f0e16f733d1c', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 16, 16, 'A resistance is found to be 12.6 ± 0.4 Ω. Calculate its percentage uncertainty.', NULL, 1, 'numeric'::answer_type, '3.175', '%', false, NULL, false, NULL, '% = 0.4 ÷ 12.6 × 100 = 3.2 %. Mark scheme (2 marks). C1: absolute ÷ value × 100. A1: % uncertainty = 3.2%.', 2, NULL, NULL),
('7beb0ea3-a447-57ea-8da1-543224271346', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 17, 17, 'Why should an experiment be repeated?', NULL, 1, 'multiple_choice'::answer_type, 'To check reliability, spot anomalous readings and reduce random error by averaging', NULL, false, NULL, false, NULL, 'Repeats deal with random, not systematic, errors. Mark scheme (1 mark). B1: B (To check reliability, spot anomalous readings and reduce random error by averaging).', 1, NULL, NULL),
('5a381b9f-7975-557b-842b-5b50213400b4', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 18, 18, 'In a specific heat capacity experiment, much energy is lost to the surroundings. Which improvement is best?', NULL, 1, 'multiple_choice'::answer_type, 'Insulate the block (lag it) and start below room temperature', NULL, false, NULL, false, NULL, 'Lagging reduces heat loss. Mark scheme (1 mark). B1: C (Insulate the block (lag it) and start below room temperature).', 1, NULL, NULL),
('b9290d3a-27ef-5ce8-81dc-18a49573a129', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 19, 19, 'A student obtains 1.52 for a quantity whose accepted value is 1.60. Calculate the percentage difference from the accepted value.', NULL, 1, 'numeric'::answer_type, '5', '%', false, NULL, false, NULL, '% = (1.60 − 1.52) ÷ 1.60 × 100 = 5.0 %. Mark scheme (2 marks). C1: difference ÷ accepted. A1: % difference = 5.0%.', 2, NULL, NULL),
('91cfa3d7-2039-5132-83be-495c24703b46', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 20, 20, 'An ammeter has a zero error. How should the readings be corrected?', NULL, 1, 'multiple_choice'::answer_type, 'Subtract the zero reading from every reading', NULL, false, NULL, false, NULL, 'A zero error is a systematic error and is corrected, not averaged. Mark scheme (1 mark). B1: A (Subtract the zero reading from every reading).', 1, NULL, NULL),
('0ef01840-5656-5c58-93d3-ca9d59c1da8f', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 21, 21, 'Does taking more repeat readings reduce a systematic error?', NULL, 1, 'multiple_choice'::answer_type, 'No, because a systematic error shifts every reading by the same amount', NULL, false, NULL, false, NULL, 'Averaging reduces only random errors. Mark scheme (1 mark). B1: D (No, because a systematic error shifts every reading by the same amount).', 1, NULL, NULL),
('8b0f28fc-db7e-5b55-92c8-5e888e784108', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 22, 22, 'A diameter is measured as 1.20 ± 0.06 mm; the manufacturer states 1.30 mm. Calculate how far the accepted value lies above the upper limit of the measurement, in mm.', NULL, 1, 'numeric'::answer_type, '0.04 mm', 'mm', false, NULL, false, NULL, 'Upper limit = 1.20 + 0.06 = 1.26 mm; gap = 1.30 − 1.26 = 0.04 mm. Mark scheme (2 marks). C1: upper limit. A1: gap = 0.04 mm.', 2, NULL, NULL),
('4b4e1c1d-9728-5f95-a4f9-2eef868aac22', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 23, 23, 'Which pair of values (experiment, theory) shows agreement within the experimental uncertainty?', NULL, 1, 'multiple_choice'::answer_type, '6.2 ± 0.3 and 6.4', NULL, false, NULL, false, NULL, 'Only 6.2 ± 0.3 has a range (5.9 to 6.5) that includes 6.4. Mark scheme (1 mark). B1: B (6.2 ± 0.3 and 6.4).', 1, NULL, NULL),
('c71af366-0628-5cf9-8411-4cba9f1ec82d', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 24, 24, 'Two students time the same event as 2.6 ± 0.1 s and 2.9 ± 0.1 s. Calculate the gap between the upper limit of the first value and the lower limit of the second.', NULL, 1, 'numeric'::answer_type, '0.1', 's', false, NULL, false, NULL, 'Upper limit of first = 2.7 s; lower limit of second = 2.8 s; gap = 2.8 − 2.7 = 0.1 s. Mark scheme (2 marks). C1: both limits. A1: gap = 0.1 s.', 2, NULL, NULL),
('2bca2524-446b-5967-bbcd-f21d61976fff', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 25, 25, 'Points on a graph are widely scattered about the best-fit line. What does this suggest?', NULL, 1, 'multiple_choice'::answer_type, 'Large random errors in the readings', NULL, false, NULL, false, NULL, 'Random errors cause scatter; systematic errors shift the line. Mark scheme (1 mark). B1: C (Large random errors in the readings).', 1, NULL, NULL),
('c2d7b07b-bb3a-5062-8e44-3c6f72788183', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 26, 26, 'A spring constant is measured as 24.6 ± 1.2 N m⁻¹; the manufacturer states 26.0 N m⁻¹. What should be concluded?', NULL, 2, 'multiple_choice'::answer_type, 'The result does not agree: the upper limit, 25.8 N m⁻¹, is below 26.0 N m⁻¹', NULL, false, NULL, false, NULL, 'Compare the accepted value with the range of the result. Mark scheme (3 marks). C1: upper limit 25.8. C1: accepted value outside range. A1: A (The result does not agree: the upper limit, 25.8 N m⁻¹, is below 26.0 N m⁻¹).', 3, NULL, NULL),
('e582fcb6-385e-57f5-95e8-9e868d5e4c0d', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 27, 27, 'A student finds g = 9.45 m s⁻² with an uncertainty of 2.0%. Calculate the percentage difference from the accepted value of 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '3.67', '%', false, NULL, false, NULL, '% difference = (9.81 − 9.45) ÷ 9.81 × 100 = 3.67 %. Mark scheme (3 marks). C1: difference. C1: ÷ accepted × 100. A1: % difference = 3.67%.', 3, NULL, NULL),
('da8cb536-2d2f-5a2a-921b-bf6faace82a2', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 28, 28, 'A result differs from the accepted value by 3.7%, while its uncertainty is 2.0%. What is the most likely explanation?', NULL, 2, 'multiple_choice'::answer_type, 'A systematic error not included in the uncertainty', NULL, false, NULL, false, NULL, 'A difference larger than the uncertainty points to an unaccounted systematic error. Mark scheme (3 marks). C1: difference > uncertainty. C1: systematic error. A1: D (A systematic error not included in the uncertainty).', 3, NULL, NULL),
('87e9135c-226d-5067-b42c-0d888afe9401', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 29, 29, 'A ball''s fall time from 0.40 m (about 0.29 s) is measured with a stopwatch. Which limitation and improvement go together?', NULL, 2, 'multiple_choice'::answer_type, 'Reaction time is large compared with the time measured; use light gates with an electronic timer', NULL, false, NULL, false, NULL, 'A reaction time of ~0.2 s is most of the fall time. Mark scheme (3 marks). C1: reaction time limitation. C1: light gates improvement. A1: B (Reaction time is large compared with the time measured; use light gates with an electronic timer).', 3, NULL, NULL),
('7a7d05c8-99f9-5dcd-82c3-ae88537acaee', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 30, 30, 'A wire''s diameter was measured once, at one end. Which limitation and improvement go together?', NULL, 2, 'multiple_choice'::answer_type, 'The wire may not be uniform; measure at several points along it and in different directions, then average', NULL, false, NULL, false, NULL, 'One reading cannot reveal variation. Mark scheme (3 marks). C1: non-uniform wire. C1: several readings averaged. A1: C (The wire may not be uniform; measure at several points along it and in different directions, then average).', 3, NULL, NULL),
('accebf08-93c1-506e-b078-960d543ed572', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 31, 31, 'A log–log graph gives n = 2.12 ± 0.10. Does this support the hypothesis that n = 2?', NULL, 2, 'multiple_choice'::answer_type, 'No: the range 2.02 to 2.22 does not include 2', NULL, false, NULL, false, NULL, 'Check whether 2 lies within n ± Δn. Mark scheme (3 marks). C1: range calculated. C1: conclusion. A1: A (No: the range 2.02 to 2.22 does not include 2).', 3, NULL, NULL),
('190a2e3d-298b-5dbc-90f9-3a423aedcb70', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 32, 32, 'A student uses large amplitudes when timing a pendulum. What is the limitation, and the improvement?', NULL, 2, 'multiple_choice'::answer_type, 'Large amplitudes change the period from 2π√(L/g); use small amplitudes (under about 10°)', NULL, false, NULL, false, NULL, 'The simple formula holds only for small angles. Mark scheme (3 marks). C1: small-angle approximation. C1: use small amplitude. A1: D (Large amplitudes change the period from 2π√(L/g); use small amplitudes (under about 10°)).', 3, NULL, NULL),
('679023bf-c36c-52a5-97c1-a8bbcc9ee70b', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 33, 33, 'In a resistance–length experiment, the wire gets warm as readings are taken. What is the limitation and its improvement?', NULL, 2, 'multiple_choice'::answer_type, 'Its resistance rises with temperature; use a small current and switch off between readings', NULL, false, NULL, false, NULL, 'Self-heating changes a control variable. Mark scheme (4 marks). C1: temperature rise. C1: R changes. C1: small current/switch off. A1: B (Its resistance rises with temperature; use a small current and switch off between readings).', 4, NULL, NULL),
('840820bd-6446-54a9-818a-4ff5c54f9668', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 34, 34, 'Which change reduces the percentage uncertainty in a measured period?', NULL, 2, 'multiple_choice'::answer_type, 'Timing a larger number of oscillations', NULL, false, NULL, false, NULL, 'The same timing uncertainty is spread over more oscillations. Mark scheme (3 marks). C1: more oscillations. C1: % = Δt/total. A1: C (Timing a larger number of oscillations).', 3, NULL, NULL),
('287bc7b6-b307-51ee-b9ef-8392786b0d33', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 35, 35, 'A specific heat capacity is measured as 4350 J kg⁻¹ K⁻¹ with an uncertainty of 6%. Calculate the lower limit of the result, in J kg⁻¹ K⁻¹.', NULL, 2, 'numeric'::answer_type, '4089', 'J kg⁻¹ K⁻¹', false, NULL, false, NULL, 'Δc = 0.06 × 4350 = 261; lower limit = 4350 − 261 = 4090 J kg⁻¹ K⁻¹. Mark scheme (3 marks). C1: absolute uncertainty. C1: subtract. A1: lower limit = 4090 J kg⁻¹ K⁻¹.', 3, NULL, NULL),
('32bb1033-a116-53ce-9be4-227bfcd8295c', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 36, 36, 'A V–I graph for a component is a straight line through the origin within its error bars. What is the conclusion?', NULL, 2, 'multiple_choice'::answer_type, 'The component obeys Ohm''s law over this range: V ∝ I', NULL, false, NULL, false, NULL, 'Proportionality means constant resistance. Mark scheme (3 marks). C1: straight line through origin. C1: constant resistance. A1: A (The component obeys Ohm''s law over this range: V ∝ I).', 3, NULL, NULL),
('e0757f14-9cb9-5c64-b158-0e6721803df8', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 37, 37, 'Calculate the percentage difference between an experimental value of 0.236 ± 0.012 and the accepted value of 0.250.', NULL, 2, 'numeric'::answer_type, '5.6', '%', false, NULL, false, NULL, '% difference = (0.250 − 0.236) ÷ 0.250 × 100 = 5.6 %. Mark scheme (3 marks). C1: difference. C1: ÷ accepted × 100. A1: % difference = 5.6%.', 3, NULL, NULL),
('0d33350a-cd4f-5d7c-865b-1786e9cedb34', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 38, 38, 'The distance from a lamp to an LDR is hard to measure because the filament is inside the bulb. Which improvement is best?', NULL, 2, 'multiple_choice'::answer_type, 'Use a small LED, or plot a graph so that the unknown offset appears as an intercept', NULL, false, NULL, false, NULL, 'An unknown constant offset can be found from a graph. Mark scheme (3 marks). C1: offset limitation. C1: point source or intercept. A1: D (Use a small LED, or plot a graph so that the unknown offset appears as an intercept).', 3, NULL, NULL),
('c31f1da9-acb5-59ac-8ea1-7416303a88f0', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 39, 39, 'A graph that should pass through the origin has a clear non-zero intercept. What does this suggest?', NULL, 2, 'multiple_choice'::answer_type, 'A systematic error, such as a zero error or an unmeasured length (for example an end correction)', NULL, false, NULL, false, NULL, 'A constant offset in every reading shifts the line. Mark scheme (3 marks). C1: systematic error. C1: example. A1: B (A systematic error, such as a zero error or an unmeasured length (for example an end correction)).', 3, NULL, NULL),
('1051ce4d-a4ac-58be-aa05-67f3531f5de7', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 40, 40, 'For a resonance tube, L = v/4f − e. A graph of L against 1/f has intercept −0.012 m on the L axis. Calculate the end correction e, in mm.', NULL, 2, 'numeric'::answer_type, '12 mm', 'mm', false, NULL, false, NULL, 'Intercept = −e, so e = 0.012 m. In mm: 0.012 × 10³ = 12. Mark scheme (4 marks). M1: intercept = −e. C1: e = 0.012 m. C1: mm. A1: e = 12 mm.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fge179330e-t fge179330e-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fge179330e-t">L against 1/f</title><desc id="fge179330e-d">A straight line on a graph of resonance length L against 1/f, meeting the L axis below the origin at −0.012 m.</desc><line x1="46.5" y1="34" x2="46.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="130.4" y1="34" x2="130.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="214.2" y1="34" x2="214.2" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="298.1" y1="34" x2="298.1" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="46.5" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="46.5" y1="216" x2="382" y2="216" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="46.5" y1="164" x2="382" y2="164" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="46.5" y1="112" x2="382" y2="112" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="46.5" y1="60" x2="382" y2="60" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="46.5" y1="216" x2="388" y2="216" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="46.5" y1="242" x2="46.5" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,216 385.7,219 385.7,213" style="fill:currentColor;stroke:none"/><polygon points="46.5,24 49.4,30.3 43.5,30.3" style="fill:currentColor;stroke:none"/><line x1="46.5" y1="216" x2="46.5" y2="220" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="46.5" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="130.4" y1="216" x2="130.4" y2="220" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="130.4" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1</text><line x1="214.2" y1="216" x2="214.2" y2="220" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="214.2" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2</text><line x1="298.1" y1="216" x2="298.1" y2="220" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="298.1" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">3</text><line x1="382" y1="216" x2="382" y2="220" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="382" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4</text><line x1="42.5" y1="242" x2="46.5" y2="242" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="39.5" y="242" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">−0.05</text><line x1="42.5" y1="216" x2="46.5" y2="216" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="39.5" y="216" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="42.5" y1="164" x2="46.5" y2="164" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="39.5" y="164" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0.10</text><line x1="42.5" y1="112" x2="46.5" y2="112" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="39.5" y="112" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0.20</text><line x1="42.5" y1="60" x2="46.5" y2="60" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="39.5" y="60" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0.30</text><text x="214.2" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">(1/f) / 10⁻³ s</text><text x="42.5" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">L / m</text><polyline points="46.5,222.2 382,45.4" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="54.5" y="234.2" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−0.012 m</text></svg>', 'A straight line on a graph of resonance length L against 1/f, meeting the L axis below the origin at −0.012 m.'),
('9695ca1e-245e-5d47-99f2-67fd81c1a3d4', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 41, 41, 'Only four readings were taken over a narrow range of the independent variable. Which improvement is best?', NULL, 2, 'multiple_choice'::answer_type, 'Take more readings (at least six) over a wider range', NULL, false, NULL, false, NULL, 'More, widely spread readings define the trend and gradient. Mark scheme (3 marks). C1: more readings. C1: wider range. A1: C (Take more readings (at least six) over a wider range).', 3, NULL, NULL),
('c0a59b32-7315-573b-abbf-6e7cd14b66ae', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 42, 42, 'A single reading in a set looks anomalous. What should the evaluation suggest?', NULL, 2, 'multiple_choice'::answer_type, 'Repeat that reading and take repeat readings for every value', NULL, false, NULL, false, NULL, 'Repeats show whether a reading is anomalous. Mark scheme (3 marks). C1: repeat. C1: check before rejecting. A1: A (Repeat that reading and take repeat readings for every value).', 3, NULL, NULL),
('608388f8-7701-5c64-86d6-bbdc57111255', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 43, 43, 'A cell''s e.m.f. is measured as 1.47 ± 0.03 V; its label says 1.50 V. Calculate the upper limit of the measurement and decide whether it agrees with the label. Give the upper limit.', NULL, 2, 'numeric'::answer_type, '1.5', 'V', false, NULL, false, NULL, 'Upper limit = 1.47 + 0.03 = 1.50 V, which equals the label value, so the measurement just agrees. Mark scheme (3 marks). C1: upper limit. C1: comparison. A1: upper limit = 1.50 V.', 3, NULL, NULL),
('d0735ba3-98a1-5dbd-9d8a-70e0f2bb8210', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 44, 44, 'A focal length is measured as 14.2 ± 0.6 cm. Calculate its percentage uncertainty.', NULL, 2, 'numeric'::answer_type, '4.225', '%', false, NULL, false, NULL, '% = 0.6 ÷ 14.2 × 100 = 4.2 %. Mark scheme (3 marks). C1: Δf/f. C1: × 100. A1: % uncertainty = 4.2%.', 3, NULL, NULL),
('cea872cc-c8a4-51af-84f9-58ec3a5ac194', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 45, 45, 'A student measures the resistivity of a wire as (5.2 ± 0.3) × 10⁻⁷ Ω m. Constantan has resistivity 4.9 × 10⁻⁷ Ω m. (a) Calculate the lower limit of the result. (b) Explain whether the wire could be constantan. Give the lower limit, in units of 10⁻⁷ Ω m.', NULL, 3, 'numeric'::answer_type, '4.9', '10⁻⁷ Ω m', false, NULL, false, NULL, '(a) Lower limit = (5.2 − 0.3) × 10⁻⁷ = 4.9 × 10⁻⁷ Ω m. (b) 4.9 lies just inside the range 4.9 to 5.5, so it could be constantan (only just). Mark scheme (5 marks). C1: lower limit. C1: upper limit. M1: compare with accepted. B1: conclusion. A1: lower limit = 4.9 × 10⁻⁷ Ω m.', 5, NULL, NULL),
('5f7d1240-1fe1-5bb0-8b74-6c482b40f941', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 46, 46, 'A graph of T² against L has gradient 4.10 ± 0.12 s² m⁻¹. (a) Calculate g. (b) Calculate its absolute uncertainty. (c) State whether the result agrees with 9.81 m s⁻². Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.2818', 'm s⁻²', false, NULL, false, NULL, '(a) g = 4π² ÷ 4.10 = 9.629 m s⁻². (b) % = 0.12 ÷ 4.10 × 100 = 2.93 %; Δg = 2.93 ÷ 100 × 9.629 = 0.28 m s⁻². (c) The range 9.35 to 9.91 includes 9.81, so it agrees. Mark scheme (6 marks). C1: g. C1: % in gradient. M1: absolute uncertainty. C1: range. B1: agrees. A1: Δg = 0.28 m s⁻².', 6, NULL, NULL),
('bca07f39-d1ba-5c4d-a265-a1cee29e9db3', '50ff4bc9-26e6-445a-abf4-2137ff76c6eb', '8b8b53aa-cac1-4dda-a21f-0e8b114d6d31', 'a-level', 'P2.5', '9702 coursebook P2.5 · Conclusions and evaluation of results', 47, 47, 'A V–I graph for a resistor gives a straight line with a clear positive intercept on the V axis, although Ohm''s law predicts a line through the origin. Which evaluation is best?', NULL, 3, 'multiple_choice'::answer_type, 'The voltmeter probably has a zero error (a systematic error); check and correct its zero, then repeat; the gradient still gives R', NULL, false, NULL, false, NULL, 'An offset in V shifts the line but leaves the gradient unchanged. Mark scheme (5 marks). C1: intercept means systematic error. C1: zero error identified. C1: correction. C1: gradient unaffected. A1: D (The voltmeter probably has a zero error (a systematic error); check and correct its zero, then repeat; the gradient still gives R).', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fgcb9f9af1-t fgcb9f9af1-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgcb9f9af1-t">V against I for a resistor</title><desc id="fgcb9f9af1-d">A V–I graph for a resistor: the best-fit line through the points is straight but meets the V axis above the origin.</desc><line x1="24" y1="34" x2="24" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="83.7" y1="34" x2="83.7" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="143.3" y1="34" x2="143.3" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="203" y1="34" x2="203" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"